insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('sunday-reset-planner', 'Sunday Reset Planner', 'worksheet'::resource_kind, 'A one-page planner for looking back over the week and choosing three things to carry into the next.', 'Use it to give a client a steady weekly rhythm of reviewing and planning.', array['Adults']::text[], '20 minutes weekly', 'Walk through the page once in session so the client knows what each box is for. Many clients fill the look-back and skip the plan; notice which half they favor and talk about it. Keep the three choices small enough to finish.', '[{"id": "f0", "type": "textarea", "label": "What went well this week?"}, {"id": "f1", "type": "textarea", "label": "What was harder than I expected?"}, {"id": "f2", "type": "textarea", "label": "What do I want to carry into next week?"}, {"id": "f3", "type": "textarea", "label": "Three small things I will do next week"}, {"id": "f4", "type": "textarea", "label": "Who or what could help me do them?"}]'::jsonb, array['planning', 'routines', 'self-monitoring']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('small-joys-collection-sheet', 'Small Joys Collection Sheet', 'worksheet'::resource_kind, 'A running list of small, ordinary moments a client noticed and enjoyed during the week.', 'Use it to help a client notice the pleasant moments that already exist in their days.', array['Adults']::text[], 'One week', 'Ask the client to jot one line whenever something small is pleasant, without rating it. Review the list in session and look for patterns in place, people and time of day. If a client finds nothing at first, shrink what counts.', '[{"id": "f0", "type": "textarea", "label": "Something small I enjoyed today"}, {"id": "f1", "type": "textarea", "label": "Where I was and who was there"}, {"id": "f2", "type": "textarea", "label": "What I noticed with my senses"}, {"id": "f3", "type": "textarea", "label": "How my body felt in that moment"}, {"id": "f4", "type": "textarea", "label": "One way to have more of this"}]'::jsonb, array['pleasant events', 'self-monitoring', 'routines']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('friction-points-audit', 'Friction Points Audit', 'worksheet'::resource_kind, 'A client lists the small daily snags that drain energy and sorts them into fix, accept or delegate.', 'Use it to turn vague daily frustration into a short list of choices a client can act on.', array['Adults']::text[], '30 minutes', 'Start by letting the client vent a little onto the page, then sort. The sorting is where the skill is, so spend your time there. Clients often discover that one fix removes several snags. Keep the action list to two items.', '[{"id": "f0", "type": "textarea", "label": "The snags that drain me most often"}, {"id": "f1", "type": "textarea", "label": "Which ones I could fix"}, {"id": "f2", "type": "textarea", "label": "Which ones I would have to accept"}, {"id": "f3", "type": "textarea", "label": "Which ones someone else could take on"}, {"id": "f4", "type": "textarea", "label": "The first change I will try this week"}]'::jsonb, array['stress', 'planning', 'boundaries']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('question-parking-lot-for-between-sessions', 'Question Parking Lot for Between Sessions', 'worksheet'::resource_kind, 'A page where a client parks questions and thoughts that come up between sessions so nothing is lost.', 'Use it to make sessions start with what matters most to the client.', array['Adults']::text[], 'Ongoing between sessions', 'Hand it over at the end of a session and ask the client to add to it as things arise. Begin the next session by reading it together and picking the top item. It also quiets the urge to rehearse every point all week.', '[{"id": "f0", "type": "textarea", "label": "A question I want to ask"}, {"id": "f1", "type": "textarea", "label": "Something I want to tell you"}, {"id": "f2", "type": "textarea", "label": "Something that confused me"}, {"id": "f3", "type": "textarea", "label": "Something I want to work on first"}, {"id": "f4", "type": "textarea", "label": "What I hope to leave the next session with"}]'::jsonb, array['session prep', 'self-monitoring', 'planning']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('weekly-recharge-menu', 'Weekly Recharge Menu', 'worksheet'::resource_kind, 'A menu of restoring activities sorted by time needed so a client can pick one that fits the day.', 'Use it to help a client choose restoring activities that match the time and energy they have.', array['Adults']::text[], '25 minutes', 'Build the menu with the client in session, with starters, mains and desserts as a light frame for five, thirty and ninety minute options. Ask what usually stops them from choosing something restoring. Post the menu where they will see it.', '[{"id": "f0", "type": "textarea", "label": "Five-minute recharges I like"}, {"id": "f1", "type": "textarea", "label": "Thirty-minute recharges I like"}, {"id": "f2", "type": "textarea", "label": "Ninety-minute recharges I like"}, {"id": "f3", "type": "textarea", "label": "What usually gets in the way"}, {"id": "f4", "type": "textarea", "label": "The one I will choose this week"}]'::jsonb, array['routines', 'self-care', 'planning']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('evidence-scale-for-one-belief', 'Evidence Scale for One Belief', 'cbt'::resource_kind, 'A client weighs the facts for and against a single belief on a two-sided scale and rates how much they believe it.', 'Use it to help a client test one belief against the facts, step by step.', array['Adults']::text[], '25 minutes', 'Choose one belief that is specific and recent. Have the client fill both sides before rating, and rate belief strength before and after. A small shift counts. Watch for evidence that is really a feeling and gently sort it.', '[{"id": "f0", "type": "textarea", "label": "The belief I am testing"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "Facts that support it"}, {"id": "f3", "type": "textarea", "label": "Facts that do not fit it"}, {"id": "f4", "type": "textarea", "label": "A more balanced way to say it"}, {"id": "f5", "type": "textarea", "label": "How strongly I believe the original now"}]'::jsonb, array['evidence', 'thinking traps', 'core CBT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('alternative-explanations-brainstorm', 'Alternative Explanations Brainstorm', 'cbt'::resource_kind, 'A client lists at least five other reasons an event could have happened besides the first one they thought of.', 'Use it to loosen a client''s first explanation by widening the list of possible explanations.', array['Adults']::text[], '20 minutes', 'Pick an event where the client jumped to a conclusion. Set a quota of five other explanations and let some be silly to lower the pressure. Then ask which are most likely given what they know. The goal is flexibility, not the right answer.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "My first explanation"}, {"id": "f2", "type": "textarea", "label": "Five other explanations"}, {"id": "f3", "type": "textarea", "label": "Which seems most likely, and why"}, {"id": "f4", "type": "textarea", "label": "What I could do to find out more"}]'::jsonb, array['thinking traps', 'evidence', 'core CBT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('assumed-thoughts-reality-check', 'Assumed Thoughts Reality Check', 'cbt'::resource_kind, 'A client writes what they assumed someone thought, then plans a way to check it.', 'Use it to help a client separate assumptions about others'' thoughts from what they actually know.', array['Adults']::text[], '20 minutes', 'Use it after a client reports a social moment that left them upset. Separate what they saw and heard from what they guessed. Then choose a low-stakes way to check, such as a simple question. Review what happened at the next visit.', '[{"id": "f0", "type": "textarea", "label": "What I think they thought"}, {"id": "f1", "type": "textarea", "label": "What I actually saw or heard"}, {"id": "f2", "type": "textarea", "label": "Other things they might have been thinking"}, {"id": "f3", "type": "textarea", "label": "One way I could check"}, {"id": "f4", "type": "textarea", "label": "What I found out"}]'::jsonb, array['thinking traps', 'communication', 'core CBT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('rules-and-musts-rewrite-page', 'Rules and Musts Rewrite Page', 'cbt'::resource_kind, 'A client finds the shoulds and musts in their self-talk and rewrites each into a preference or a choice.', 'Use it to soften rigid self-talk into language that leaves room for choices.', array['Adults']::text[], '20 minutes', 'Ask the client to listen for should, must and have to over a few days, then bring the list. Rewrite two together as a model. Notice how the body feels when the wording changes. Rules that serve a value can stay; rules that only press can be reworded.', '[{"id": "f0", "type": "textarea", "label": "A should I tell myself"}, {"id": "f1", "type": "textarea", "label": "Where I learned it"}, {"id": "f2", "type": "textarea", "label": "How it makes me feel"}, {"id": "f3", "type": "textarea", "label": "A rewrite as a preference or choice"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend with the same should"}]'::jsonb, array['self-talk', 'cognitive restructuring', 'core CBT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('feeling-versus-fact-pause-sheet', 'Feeling Versus Fact Pause Sheet', 'cbt'::resource_kind, 'A client separates how it feels from what is known when a strong feeling is being treated as proof.', 'Use it to help a client pause when a strong feeling starts to sound like a fact.', array['Adults']::text[], '20 minutes', 'Strong feelings are real; the work is about not treating them as proof of what will happen. Name the feeling first so it is respected, then look at the facts apart from it. Practice on a small example before a bigger one.', '[{"id": "f0", "type": "textarea", "label": "The feeling I notice, and how strong it is"}, {"id": "f1", "type": "textarea", "label": "What the feeling is telling me"}, {"id": "f2", "type": "textarea", "label": "The facts apart from the feeling"}, {"id": "f3", "type": "textarea", "label": "What else could be true"}, {"id": "f4", "type": "textarea", "label": "What I want to do given all of this"}]'::jsonb, array['thinking traps', 'emotion identification', 'core CBT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('struggle-switch-sketch', 'Struggle Switch Sketch', 'act'::resource_kind, 'A client draws a switch labeled struggle and writes what happens to a feeling when they fight it.', 'Use it to help a client see how fighting a feeling can add to it.', array['Adults']::text[], '20 minutes', 'The struggle switch is a familiar metaphor from ACT. Have the client draw the switch on and off, with and without the feeling. Ask what changes when the switch is off. Stay curious and avoid selling it as a fix; the client decides what fits.', '[{"id": "f0", "type": "textarea", "label": "A feeling I often struggle with"}, {"id": "f1", "type": "textarea", "label": "What I do when the switch is on"}, {"id": "f2", "type": "textarea", "label": "What it costs me"}, {"id": "f3", "type": "textarea", "label": "What it might look like with the switch off"}, {"id": "f4", "type": "textarea", "label": "One small moment this week to try it"}]'::jsonb, array['acceptance', 'willingness', 'core ACT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('hands-as-thoughts-exercise-notes', 'Hands as Thoughts Exercise Notes', 'act'::resource_kind, 'A note page for the exercise where thoughts are held up to the face and then held at arm''s length.', 'Use it to give a client a physical way to feel the difference of holding a thought at a distance.', array['Adults']::text[], '15 minutes', 'Have the client press their palms to their face and describe what they can and cannot do, then lower them to the lap. Walk through the experience, then use the page for what they noticed. Keep it playful and invite them to try it at home.', '[{"id": "f0", "type": "textarea", "label": "A thought I held up close"}, {"id": "f1", "type": "textarea", "label": "What it was like to do things with my hands over my face"}, {"id": "f2", "type": "textarea", "label": "What changed when I moved my hands away"}, {"id": "f3", "type": "textarea", "label": "Where I could use this in my week"}]'::jsonb, array['defusion', 'metaphor', 'core ACT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('finger-trap-reflection-page', 'Finger Trap Reflection Page', 'act'::resource_kind, 'A reflection page for the finger trap exercise about what happens when pulling harder makes the trap tighter.', 'Use it to illustrate that more effort can sometimes make a stuck feeling feel more stuck.', array['Adults']::text[], '15 minutes', 'A finger trap toy makes the point without lecturing. Let the client pull, then try easing in. Use the page for what they noticed and where their life looks like the trap. Hold your own interpretation lightly.', '[{"id": "f0", "type": "textarea", "label": "What happened when I pulled hard"}, {"id": "f1", "type": "textarea", "label": "What happened when I eased in"}, {"id": "f2", "type": "textarea", "label": "A place in my life that feels like this"}, {"id": "f3", "type": "textarea", "label": "What easing in could look like there"}, {"id": "f4", "type": "textarea", "label": "What I want to remember"}]'::jsonb, array['willingness', 'metaphor', 'core ACT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('values-based-habit-starter', 'Values-Based Habit Starter', 'act'::resource_kind, 'A client names a value, picks one tiny action that expresses it, and plans when and where it will happen.', 'Use it to turn a value into a very small action that fits into the week.', array['Adults']::text[], '25 minutes', 'Choose one value the client cares about, then the smallest action that honors it. Anchor it to an existing routine. The client defines success as doing it, not how it felt. Check in on obstacles and shrink the action if needed.', '[{"id": "f0", "type": "textarea", "label": "A value I care about"}, {"id": "f1", "type": "textarea", "label": "A tiny action that expresses it"}, {"id": "f2", "type": "textarea", "label": "When and where I will do it"}, {"id": "f3", "type": "textarea", "label": "What might get in the way"}, {"id": "f4", "type": "textarea", "label": "What I will do if it does"}, {"id": "f5", "type": "textarea", "label": "How I will notice that I did it"}]'::jsonb, array['values', 'committed action', 'core ACT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('self-compassion-pause-practice', 'Self-Compassion Pause Practice', 'act'::resource_kind, 'A short practice sheet for pausing in a hard moment, naming it, and offering oneself a kind line.', 'Use it to give a client a brief practice for meeting a painful moment with kindness.', array['Adults']::text[], 'Five minutes daily', 'Teach the pause in session first: notice, name it, remember that others struggle too, then offer a kind phrase in the client''s own words. Some clients resist warmth toward themselves; offer it as an experiment and ask what happened.', '[{"id": "f0", "type": "textarea", "label": "A hard moment I noticed"}, {"id": "f1", "type": "textarea", "label": "What I called it"}, {"id": "f2", "type": "textarea", "label": "A kind sentence in my own words"}, {"id": "f3", "type": "textarea", "label": "What changed, even a little"}, {"id": "f4", "type": "textarea", "label": "When I will practice next"}]'::jsonb, array['self-compassion', 'mindfulness', 'core ACT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('coping-ahead-plan-for-a-hard-event', 'Coping Ahead Plan for a Hard Event', 'dbt'::resource_kind, 'A client rehearses an upcoming difficult event step by step and lists the skills they will use.', 'Use it to prepare a client for an event they expect to be hard by planning skills in advance.', array['Adults']::text[], '30 minutes', 'This is the DBT skill of coping ahead. Choose a real event in the next week. Help the client picture it in detail, name the likely emotions and urges, and pick specific skills. Have them rehearse the plan out loud before leaving.', '[{"id": "f0", "type": "textarea", "label": "The event I am preparing for"}, {"id": "f1", "type": "textarea", "label": "What I expect to feel"}, {"id": "f2", "type": "textarea", "label": "Urges I might notice"}, {"id": "f3", "type": "textarea", "label": "Skills I will use and when"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself"}, {"id": "f5", "type": "textarea", "label": "What I will do after"}]'::jsonb, array['coping ahead', 'emotion regulation', 'core DBT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('please-body-care-weekly-log', 'PLEASE Body Care Weekly Log', 'dbt'::resource_kind, 'A weekly tracker for the PLEASE skills: body care, rest, eating pattern, activity and substance use.', 'Use it to help a client see how basic body care connects with how they feel.', array['Adults']::text[], 'One week', 'PLEASE is a DBT skill for lowering emotional vulnerability. Keep the tracker neutral and free of judgment; the point is noticing links between sleep, activity, and mood. Pick one row to change at a time with the client''s agreement.', '[{"id": "f0", "type": "textarea", "label": "Sleep this week and how I felt"}, {"id": "f1", "type": "textarea", "label": "Activity this week and how I felt"}, {"id": "f2", "type": "textarea", "label": "How I cared for my body"}, {"id": "f3", "type": "textarea", "label": "What I notice about the links"}, {"id": "f4", "type": "textarea", "label": "One row I want to change"}]'::jsonb, array['emotion regulation', 'self-monitoring', 'core DBT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('half-smile-and-willing-hands-practice', 'Half-Smile and Willing Hands Practice', 'dbt'::resource_kind, 'A practice sheet for using body posture to practice acceptance during a hard moment.', 'Use it to give a client a body-based way to practice accepting a hard moment.', array['Adults']::text[], 'Five minutes daily', 'Teach the half-smile and willing hands in session first. Invite the client to practice at a calm moment and then at a mildly hard one. Be open about the fact that some clients feel awkward at first; ask what they notice rather than what they should.', '[{"id": "f0", "type": "textarea", "label": "When I practiced"}, {"id": "f1", "type": "textarea", "label": "What my body felt like"}, {"id": "f2", "type": "textarea", "label": "What changed or did not"}, {"id": "f3", "type": "textarea", "label": "A mildly hard moment I could try it in"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterwards"}]'::jsonb, array['acceptance', 'distress tolerance', 'core DBT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('build-mastery-daily-pick', 'Build Mastery Daily Pick', 'dbt'::resource_kind, 'A client picks one task a day that is hard enough to feel capable afterwards and logs how it felt.', 'Use it to help a client build a sense of capability through one doable challenge a day.', array['Adults']::text[], 'One week', 'Build mastery is part of the DBT emotion regulation skills. Help the client choose tasks that are just beyond comfortable, not overwhelming. The log tracks completion and how it felt. Celebrate effort, not perfection.', '[{"id": "f0", "type": "textarea", "label": "Today''s mastery pick"}, {"id": "f1", "type": "textarea", "label": "Why I chose it"}, {"id": "f2", "type": "textarea", "label": "Did I do it, and how long"}, {"id": "f3", "type": "textarea", "label": "How I felt after"}, {"id": "f4", "type": "textarea", "label": "Tomorrow''s pick"}]'::jsonb, array['mastery', 'emotion regulation', 'core DBT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('accumulating-positives-planner', 'Accumulating Positives Planner', 'dbt'::resource_kind, 'A planner for adding pleasant events to a client''s week now and working toward a longer-term goal.', 'Use it to help a client build more positive experiences into daily life.', array['Adults']::text[], '25 minutes', 'This is the short and long term accumulating positives skill. Ask for activities the client truly enjoys, not ones they think they should. Tie the long-term part to a value. Check what stops the client from doing the pleasant event.', '[{"id": "f0", "type": "textarea", "label": "Pleasant events I could do this week"}, {"id": "f1", "type": "textarea", "label": "One I will do and when"}, {"id": "f2", "type": "textarea", "label": "A long-term goal I care about"}, {"id": "f3", "type": "textarea", "label": "A small step toward it"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['pleasant events', 'emotion regulation', 'core DBT']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('appreciation-before-request-script', 'Appreciation Before Request Script', 'couples'::resource_kind, 'Each partner practices opening a request with a specific thank-you before asking for what they need.', 'Use it to help partners make requests that are easier to hear.', array['Couples']::text[], '30 minutes', 'Each partner completes their own side first, then you coach them aloud with one turn each. The appreciation must be specific and true. Notice if either partner uses the thanks as a setup; if so, slow down and try again.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something specific I appreciate"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I would like to ask for"}, {"id": "f2", "type": "textarea", "label": "Partner B: something specific I appreciate"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I would like to ask for"}, {"id": "f4", "type": "textarea", "label": "What it was like to hear the thank-you first"}]'::jsonb, array['communication', 'appreciation', 'couples']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('money-talk-starter-sheet', 'Money Talk Starter Sheet', 'couples'::resource_kind, 'A structured page that gives two partners a calm way to begin a conversation about money.', 'Use it to help partners start a money conversation with shared goals rather than blame.', array['Couples']::text[], '45 minutes', 'Have each partner fill in their own side privately, then share one section at a time. Start with values and goals before numbers. You are not advising on finances; you are coaching the conversation. Stop and reset if either partner escalates.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what money means to me"}, {"id": "f1", "type": "textarea", "label": "Partner B: what money means to me"}, {"id": "f2", "type": "textarea", "label": "One shared goal for our money"}, {"id": "f3", "type": "textarea", "label": "One worry each of us has"}, {"id": "f4", "type": "textarea", "label": "One small step we agree on"}]'::jsonb, array['money', 'communication', 'couples']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('chore-wheel-negotiation-sheet', 'Chore Wheel Negotiation Sheet', 'couples'::resource_kind, 'Partners list household tasks, rate how much each dislikes them, and trade until the split feels fair.', 'Use it to help partners negotiate the load of household tasks without scorekeeping.', array['Couples']::text[], '40 minutes', 'List every task, including mental load such as planning and remembering. Each partner rates their dislike privately. Then trade tasks out loud. Fairness may not mean equal; aim for a split both can live with and agree to revisit.', '[{"id": "f0", "type": "textarea", "label": "Tasks we each do now"}, {"id": "f1", "type": "textarea", "label": "Tasks we each dislike most"}, {"id": "f2", "type": "textarea", "label": "Tasks we each do not mind"}, {"id": "f3", "type": "textarea", "label": "A trade we both agree to try"}, {"id": "f4", "type": "textarea", "label": "When we will check in on how it is going"}]'::jsonb, array['fairness', 'routines', 'couples']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('reconnection-after-time-apart-plan', 'Reconnection After Time Apart Plan', 'couples'::resource_kind, 'Partners plan the first hour after a trip or a busy stretch so they can reconnect before logistics take over.', 'Use it to help partners rejoin each other warmly after time apart.', array['Couples']::text[], '20 minutes', 'Ask each partner what they need on return, then build a shared plan. Often one wants space and the other wants contact. Name both needs as valid and find a middle path. Try it out in the coming week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need when we reunite"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need when we reunite"}, {"id": "f2", "type": "textarea", "label": "A small ritual we can both do"}, {"id": "f3", "type": "textarea", "label": "What we will leave until later"}, {"id": "f4", "type": "textarea", "label": "How we will tell each other if it is not working"}]'::jsonb, array['connection', 'routines', 'couples']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('shared-hopes-for-the-next-year', 'Shared Hopes for the Next Year', 'couples'::resource_kind, 'Partners separately list their hopes for the coming year and then combine them into a shared page.', 'Use it to help partners talk about what they want ahead, not only what is wrong now.', array['Couples']::text[], '45 minutes', 'Ask for hopes in a few areas such as home, health, fun and work. Share one area at a time and listen without arguing. Where hopes differ, note it and come back later. End with one thing they can start this month.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my hopes for us this year"}, {"id": "f1", "type": "textarea", "label": "Partner B: my hopes for us this year"}, {"id": "f2", "type": "textarea", "label": "Hopes we share"}, {"id": "f3", "type": "textarea", "label": "Hopes we need to talk more about"}, {"id": "f4", "type": "textarea", "label": "One thing we can start this month"}]'::jsonb, array['values', 'communication', 'couples']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('feelings-playdough-faces', 'Feelings Playdough Faces', 'kids'::resource_kind, 'A child shapes feelings faces from playdough and tells what makes each one show up.', 'Use it to help a child name and show feelings through hands-on making.', array['Children']::text[], '25 minutes', 'The child makes a face for each feeling in playdough and says when it visits. The parent joins by making one too and listens without fixing. Offer a few feeling names if the child is stuck. Keep it light.', '[{"id": "f0", "type": "textarea", "label": "A feeling I made"}, {"id": "f1", "type": "textarea", "label": "What makes it show up"}, {"id": "f2", "type": "textarea", "label": "What it feels like in my body"}, {"id": "f3", "type": "textarea", "label": "What helps when it is big"}, {"id": "f4", "type": "textarea", "label": "A feeling I would like to make next"}]'::jsonb, array['children', 'emotion identification', 'play']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('calm-corner-design-plan', 'Calm Corner Design Plan', 'kids'::resource_kind, 'A child designs a small calm corner at home with a parent and chooses what goes in it.', 'Use it to give a child a say in a calm space they will actually want to use.', array['Children']::text[], '30 minutes', 'The child draws or builds the corner and picks items such as a cushion, a book and a squeeze toy. The parent agrees it is a place to rest, never a punishment, and that nobody follows the child in. Visit it together first when calm.', '[{"id": "f0", "type": "textarea", "label": "What I want in my calm corner"}, {"id": "f1", "type": "textarea", "label": "What it looks like"}, {"id": "f2", "type": "textarea", "label": "How I feel when I am there"}, {"id": "f3", "type": "textarea", "label": "Who can come to the corner and when"}, {"id": "f4", "type": "textarea", "label": "A name for my calm corner"}]'::jsonb, array['children', 'regulation', 'art']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('kindness-garden-chart', 'Kindness Garden Chart', 'kids'::resource_kind, 'A child colors in a flower on a garden each time they notice or do something kind.', 'Use it to help a child notice kindness given and received through a colorful chart.', array['Children']::text[], 'One week', 'The child draws a garden and colors one petal for each kindness. The parent points out kindnesses the child does and notes ones the child received. Celebrate noticing, not counting. Do not take petals away.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I did"}, {"id": "f1", "type": "textarea", "label": "A kind thing someone did for me"}, {"id": "f2", "type": "textarea", "label": "How it felt"}, {"id": "f3", "type": "textarea", "label": "Someone I want to be kind to next"}]'::jsonb, array['children', 'strengths', 'art']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('bedtime-worry-box', 'Bedtime Worry Box', 'kids'::resource_kind, 'A child decorates a small box for putting worries into before bed so they can rest.', 'Use it to give a child a bedtime ritual for setting worries down until morning.', array['Children']::text[], '30 minutes', 'The child decorates a box, writes or draws worries on slips of paper and puts them in. The parent listens for a minute, then closes the lid and says they will look at them tomorrow. Keep the ritual short and consistent.', '[{"id": "f0", "type": "textarea", "label": "A worry I put in the box"}, {"id": "f1", "type": "textarea", "label": "What it looked like in my mind"}, {"id": "f2", "type": "textarea", "label": "What I did to close the lid"}, {"id": "f3", "type": "textarea", "label": "What I can think of instead at bedtime"}, {"id": "f4", "type": "textarea", "label": "Who I can tell if I still feel worried"}]'::jsonb, array['children', 'worry', 'routines']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('brave-animal-mask', 'Brave Animal Mask', 'kids'::resource_kind, 'A child makes a mask of an animal they feel is brave and uses it to rehearse a scary step.', 'Use it to help a child borrow courage by playing a brave animal.', array['Children']::text[], '30 minutes', 'The child makes a mask from paper and markers and chooses an animal for its courage. The parent plays too, wearing a mask of their own. Together they rehearse one small scary step. Practice at home with praise for trying.', '[{"id": "f0", "type": "textarea", "label": "The animal I chose and why it is brave"}, {"id": "f1", "type": "textarea", "label": "A scary thing I want to try"}, {"id": "f2", "type": "textarea", "label": "What my animal would say to me"}, {"id": "f3", "type": "textarea", "label": "What my animal would do first"}, {"id": "f4", "type": "textarea", "label": "How I felt after trying"}]'::jsonb, array['children', 'exposure', 'play']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('values-in-motion-charades', 'Values in Motion Charades', 'game'::resource_kind, 'Players act out a value or a values-driven action while others guess, then talk about what it meant to them.', 'Use it to get a group talking about values in a playful way.', array['Groups']::text[], '30 minutes', 'Write values on slips such as kindness, courage and curiosity. Players take turns acting without words. After each guess, ask what the value looks like in daily life. Debrief with where each person would like more of it.', '[{"id": "f0", "type": "textarea", "label": "A value I acted out or guessed"}, {"id": "f1", "type": "textarea", "label": "What it looks like in my life"}, {"id": "f2", "type": "textarea", "label": "Where I would like more of it"}, {"id": "f3", "type": "textarea", "label": "One action I will try this week"}]'::jsonb, array['values', 'group', 'play']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('skills-trivia-showdown', 'Skills Trivia Showdown', 'game'::resource_kind, 'Teams answer trivia cards about coping skills and earn points by sharing how they have used each skill.', 'Use it to refresh a group''s knowledge of skills in a lively way.', array['Groups']::text[], '40 minutes', 'Split into two teams. Read a card about a skill, a team answers, then shares a real example for a bonus. Points are for sharing, not winning. Debrief by naming one skill each person wants to try this week.', '[{"id": "f0", "type": "textarea", "label": "A skill I remembered"}, {"id": "f1", "type": "textarea", "label": "A time I used it"}, {"id": "f2", "type": "textarea", "label": "A skill I forgot about"}, {"id": "f3", "type": "textarea", "label": "A skill I will try this week"}]'::jsonb, array['skills', 'group', 'play']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('strength-guess-circle', 'Strength Guess Circle', 'game'::resource_kind, 'Each player gives two true facts and one strength, and the group guesses which is the strength.', 'Use it to help a group get to know each other and name strengths out loud.', array['Groups']::text[], '25 minutes', 'Model it first with your own example. Players take turns and the group guesses which statement is the strength. After each round, the group adds one thing they see in the person. Keep the tone warm and set a no-teasing rule.', '[{"id": "f0", "type": "textarea", "label": "My two truths and my strength"}, {"id": "f1", "type": "textarea", "label": "What it was like to name a strength"}, {"id": "f2", "type": "textarea", "label": "A strength I heard in someone else"}, {"id": "f3", "type": "textarea", "label": "A strength I want to use this week"}]'::jsonb, array['strengths', 'group', 'play']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('mindful-mystery-bag', 'Mindful Mystery Bag', 'game'::resource_kind, 'Players feel an item in a bag without looking, describe it in detail, and tie the focus to everyday mindfulness.', 'Use it to give a group a playful way to practice paying attention to the present moment.', array['Groups']::text[], '20 minutes', 'Fill a bag with ordinary items such as a shell, a key and a soft cloth. Each player describes the item by touch only before the group guesses. Debrief on how attention felt and what pulled it away. Link to daily use.', '[{"id": "f0", "type": "textarea", "label": "What I noticed while I felt the item"}, {"id": "f1", "type": "textarea", "label": "What pulled my attention away"}, {"id": "f2", "type": "textarea", "label": "How I brought it back"}, {"id": "f3", "type": "textarea", "label": "A daily moment to practice this"}]'::jsonb, array['mindfulness', 'group', 'play']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('feelings-tag', 'Feelings Tag', 'game'::resource_kind, 'A movement game where players tag each other and name a feeling before freezing in a pose that shows it.', 'Use it to help children and groups connect feelings to body posture through movement.', array['Children', 'Groups']::text[], '20 minutes', 'Needs enough space to move. The tagged player names a feeling and freezes in a pose. The group guesses what the body is showing. Pause often for calm breaths. Debrief on what bodies do with different feelings.', '[{"id": "f0", "type": "textarea", "label": "A feeling I showed"}, {"id": "f1", "type": "textarea", "label": "What my body did"}, {"id": "f2", "type": "textarea", "label": "A feeling that was hard to show"}, {"id": "f3", "type": "textarea", "label": "What helps my body when a feeling is big"}]'::jsonb, array['emotion identification', 'play', 'children']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('stuck-point-spotting-sheet', 'Stuck Point Spotting Sheet', 'cbt'::resource_kind, 'A client notes beliefs that feel stuck after hard events and sorts them by what they say about safety, trust or control.', 'Use it to help a client spot recurring beliefs without retelling what happened.', array['Adults']::text[], '25 minutes', 'Work only with present-day beliefs and leave out the details of the event. The client lists beliefs in a sentence each and sorts by theme. Pace the session and stop to ground if the client gets activated. Choose one belief to look at more closely together.', '[{"id": "f0", "type": "textarea", "label": "A belief that keeps coming back"}, {"id": "f1", "type": "textarea", "label": "Which theme it fits: safety, trust, control or other"}, {"id": "f2", "type": "textarea", "label": "How strongly I believe it today"}, {"id": "f3", "type": "textarea", "label": "What I notice in my body when I think it"}, {"id": "f4", "type": "textarea", "label": "One small fact that does not fit it"}]'::jsonb, array['thinking traps', 'stabilizing', 'core CBT', 'PTSD and trauma']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('weekly-window-check-in', 'Weekly Window Check-In', 'worksheet'::resource_kind, 'A short daily check of how settled or activated a client feels, with a skill matched to each zone.', 'Use it to help a client notice their activation level and match a stabilizing skill to it.', array['Adults']::text[], 'Five minutes daily', 'Teach the three zones in session: too revved, steady, too shut down. The client ticks the zone morning and evening and picks a skill from a short list. Review patterns, not content. Leave the details of what happened out of the log.', '[{"id": "f0", "type": "textarea", "label": "Morning: where I am today"}, {"id": "f1", "type": "textarea", "label": "What I will do if I move out of steady"}, {"id": "f2", "type": "textarea", "label": "Evening: where I am now"}, {"id": "f3", "type": "textarea", "label": "What helped me today"}, {"id": "f4", "type": "textarea", "label": "What I want help with next session"}]'::jsonb, array['self-monitoring', 'stabilizing', 'grounding', 'PTSD and trauma']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('five-details-anchor-practice', 'Five Details Anchor Practice', 'act'::resource_kind, 'A client practices noticing five present-moment details and returning to them when old memories pull them away.', 'Use it to give a client a way to return to the present when the past feels close.', array['Adults']::text[], 'Five minutes daily', 'Practice the anchoring in session at a calm level first. The client notes what they see, hear and feel in the room. They also choose a value to move toward after. Ask the client to stop the practice if it increases distress.', '[{"id": "f0", "type": "textarea", "label": "Five things I can see right now"}, {"id": "f1", "type": "textarea", "label": "Three things I can hear"}, {"id": "f2", "type": "textarea", "label": "Something I can feel against my body"}, {"id": "f3", "type": "textarea", "label": "A time this week I want to use it"}, {"id": "f4", "type": "textarea", "label": "What matters to me that I can do after"}]'::jsonb, array['grounding', 'mindfulness', 'core ACT', 'PTSD and trauma']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('self-soothe-kit-for-hard-nights', 'Self-Soothe Kit for Hard Nights', 'dbt'::resource_kind, 'A client packs a small kit of comforting items for the five senses to use when nights feel unsettled.', 'Use it to help a client prepare comforting things before a hard night arrives.', array['Adults']::text[], '30 minutes', 'Build the list with the client in session and encourage them to assemble a physical kit. Include sight, sound, smell, taste and touch. Ask which items work and which do not; there is no right set. If the nights feel unsafe, review safety supports and provide 988 (call or text) as a resource.', '[{"id": "f0", "type": "textarea", "label": "A sight that comforts me"}, {"id": "f1", "type": "textarea", "label": "A sound that comforts me"}, {"id": "f2", "type": "textarea", "label": "A smell that comforts me"}, {"id": "f3", "type": "textarea", "label": "A taste that comforts me"}, {"id": "f4", "type": "textarea", "label": "A touch that comforts me"}, {"id": "f5", "type": "textarea", "label": "Who I can reach if a night feels too hard, and 988 (call or text) if I feel unsafe"}]'::jsonb, array['self-soothing', 'stabilizing', 'core DBT', 'PTSD and trauma']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('safe-place-drawing-book', 'Safe Place Drawing Book', 'kids'::resource_kind, 'A child draws a safe place and the people and things that help them feel safe, one page at a time.', 'Use it to help a child build a picture of safety through drawing, with a trusted adult nearby.', array['Children']::text[], '30 minutes', 'The child draws safe places and safe people while a parent or trusted adult sits nearby. Do not ask about what happened. If a child discloses anything, remember your duties to report and respond calmly. Keep the book and look at it together.', '[{"id": "f0", "type": "textarea", "label": "My safe place looks like"}, {"id": "f1", "type": "textarea", "label": "Who is in my safe place"}, {"id": "f2", "type": "textarea", "label": "What I can hear or smell there"}, {"id": "f3", "type": "textarea", "label": "Who helps me feel safe"}, {"id": "f4", "type": "textarea", "label": "What I can do when I feel scared"}]'::jsonb, array['children', 'safety', 'art', 'PTSD and trauma']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('worry-time-boundary-card', 'Worry Time Boundary Card', 'worksheet'::resource_kind, 'A client sets a daily worry window and writes down where worries wait until then.', 'Use it to help a client contain worry in a set slot instead of letting it fill the day.', array['Adults']::text[], 'Ten minutes daily', 'Agree on a 15-minute window, not near bedtime. Worries that appear earlier get a quick note and wait. Many clients find fewer worries remain by the window. Check in on whether the window helped or turned into extra worrying.', '[{"id": "f0", "type": "textarea", "label": "My worry time is"}, {"id": "f1", "type": "textarea", "label": "Worries I noted outside it"}, {"id": "f2", "type": "textarea", "label": "What I did when one tried to pull me in"}, {"id": "f3", "type": "textarea", "label": "Which ones still matter during worry time"}, {"id": "f4", "type": "textarea", "label": "What I will do right after worry time"}]'::jsonb, array['worry', 'routines', 'self-monitoring', 'anxiety']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('probability-and-coping-estimate', 'Probability and Coping Estimate', 'cbt'::resource_kind, 'A client rates how likely a feared event is and how well they could cope if it happened.', 'Use it to separate how likely a feared event feels from how well a client could cope with it.', array['Adults']::text[], '20 minutes', 'Ask for a specific worry, then two ratings. Most people overrate the first and underrate the second. Brainstorm actual coping steps to support the second rating. Return later to compare predictions with what happened.', '[{"id": "f0", "type": "textarea", "label": "The worry in one sentence"}, {"id": "f1", "type": "textarea", "label": "How likely it is, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "If it happened, what I could do"}, {"id": "f3", "type": "textarea", "label": "How well I could cope, 0 to 100"}, {"id": "f4", "type": "textarea", "label": "What I learned when I looked at both"}]'::jsonb, array['worry', 'uncertainty', 'core CBT', 'anxiety']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('anxiety-as-a-passenger-role-play', 'Anxiety as a Passenger Role-Play', 'act'::resource_kind, 'A client practices carrying anxiety along while driving toward something that matters.', 'Use it to help a client act on what matters while anxiety comes along.', array['Adults']::text[], '25 minutes', 'Use the idea of anxiety riding along. The client names what matters, then the action they will take with anxiety present. Role-play the step, then plan it for the week. Do not promise the feeling will fade.', '[{"id": "f0", "type": "textarea", "label": "Something that matters to me"}, {"id": "f1", "type": "textarea", "label": "What anxiety says when I move toward it"}, {"id": "f2", "type": "textarea", "label": "One step I will take with anxiety on board"}, {"id": "f3", "type": "textarea", "label": "How I will talk to the passenger"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['values', 'willingness', 'core ACT', 'anxiety']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('wave-riding-anxiety-plan', 'Wave Riding Anxiety Plan', 'dbt'::resource_kind, 'A client rides the rise and fall of an anxious wave with a plan for what to do at each stage.', 'Use it to help a client stay with an anxious surge while using skills that help it pass.', array['Adults']::text[], '25 minutes', 'Draw a wave and mark where anxiety starts, peaks and settles. The client lists skills for each stage such as paced breathing or cold water on the face. Practice one in session. Encourage noticing that waves tend to shift.', '[{"id": "f0", "type": "textarea", "label": "What it feels like as the wave builds"}, {"id": "f1", "type": "textarea", "label": "Skills I will use at the start"}, {"id": "f2", "type": "textarea", "label": "What I will do at the peak"}, {"id": "f3", "type": "textarea", "label": "What helps it settle"}, {"id": "f4", "type": "textarea", "label": "What I noticed about how long it lasted"}]'::jsonb, array['distress tolerance', 'breathing', 'core DBT', 'anxiety']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('anxiety-dice-challenge', 'Anxiety Dice Challenge', 'game'::resource_kind, 'Players roll dice to pick a small brave action and a coping skill, then share how it went.', 'Use it to make small acts of approach feel playful for a group working on anxiety.', array['Groups']::text[], '30 minutes', 'Make a card set of small, safe challenges and a card set of skills. Each player rolls and does one of each, or describes how they would. No one is pushed to do more than they choose. Debrief on what made it easier.', '[{"id": "f0", "type": "textarea", "label": "The challenge I rolled"}, {"id": "f1", "type": "textarea", "label": "The skill I used"}, {"id": "f2", "type": "textarea", "label": "How anxious I felt before and after"}, {"id": "f3", "type": "textarea", "label": "What I learned"}, {"id": "f4", "type": "textarea", "label": "What I will try this week"}]'::jsonb, array['exposure', 'group', 'play', 'anxiety']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('low-energy-day-floor-menu', 'Low Energy Day Floor Menu', 'worksheet'::resource_kind, 'A client lists minimum, middle and best-day versions of a few daily tasks so a low day does not become zero.', 'Use it to help a client keep a floor of activity on low-energy days.', array['Adults']::text[], '25 minutes', 'Choose three tasks such as washing up, moving and contact. Write a tiny, medium and full version of each. On a low day the client does the tiny one and counts it. Review what felt doable and adjust.', '[{"id": "f0", "type": "textarea", "label": "Task one: tiny, medium, full"}, {"id": "f1", "type": "textarea", "label": "Task two: tiny, medium, full"}, {"id": "f2", "type": "textarea", "label": "Task three: tiny, medium, full"}, {"id": "f3", "type": "textarea", "label": "Where I will keep the menu"}, {"id": "f4", "type": "textarea", "label": "How I will treat myself on a tiny day"}]'::jsonb, array['low mood', 'routines', 'planning', 'depression']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('mood-and-activity-link-grid', 'Mood and Activity Link Grid', 'cbt'::resource_kind, 'A client logs activities and mood for several days and looks for links between them.', 'Use it to show a client how what they do and how they feel move together.', array['Adults']::text[], 'One week', 'Ask for a short note on what they did and a mood rating for each part of the day. At review, look for activities that lifted or lowered mood by even a point. Avoid reading it as a verdict on the client; it is a map. Pick one thing to try more of.', '[{"id": "f0", "type": "textarea", "label": "Morning: what I did and my mood"}, {"id": "f1", "type": "textarea", "label": "Afternoon: what I did and my mood"}, {"id": "f2", "type": "textarea", "label": "Evening: what I did and my mood"}, {"id": "f3", "type": "textarea", "label": "The activity that helped most"}, {"id": "f4", "type": "textarea", "label": "The activity I want to try more of"}]'::jsonb, array['behavioral activation', 'self-monitoring', 'core CBT', 'depression']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('values-when-motivation-is-missing', 'Values When Motivation Is Missing', 'act'::resource_kind, 'A client picks an action tied to a value and does it without waiting to feel like it.', 'Use it to help a client act on a value even when motivation is low.', array['Adults']::text[], '25 minutes', 'Explore the idea that action can come before motivation. Choose a small action tied to a value, like texting a friend. Ask what the mind says and make room for it. Review whether acting made any difference to the day.', '[{"id": "f0", "type": "textarea", "label": "A value I care about"}, {"id": "f1", "type": "textarea", "label": "A small action that fits it"}, {"id": "f2", "type": "textarea", "label": "What my mind says about doing it"}, {"id": "f3", "type": "textarea", "label": "What I will do anyway"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['values', 'committed action', 'core ACT', 'depression']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-withdrawing', 'Opposite Action to Withdrawing', 'dbt'::resource_kind, 'A client notices the urge to withdraw, checks whether it fits the facts, and plans a small opposite action.', 'Use it to help a client try the opposite of an urge to pull away when it does not fit the facts.', array['Adults']::text[], '25 minutes', 'Name the emotion, the urge and check the facts. If withdrawing does not fit the facts or help the client''s goals, plan a small opposite step such as a short walk or a brief call. Keep it small and doable. Review afterward.', '[{"id": "f0", "type": "textarea", "label": "The feeling and the urge to withdraw"}, {"id": "f1", "type": "textarea", "label": "Does the urge fit the facts"}, {"id": "f2", "type": "textarea", "label": "A small opposite action"}, {"id": "f3", "type": "textarea", "label": "When and where I will do it"}, {"id": "f4", "type": "textarea", "label": "What happened to the feeling"}]'::jsonb, array['opposite action', 'behavioral activation', 'core DBT', 'depression']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('partner-check-in-for-heavy-days', 'Partner Check-In for Heavy Days', 'couples'::resource_kind, 'Partners agree on how one will signal a heavy day and how the other will respond helpfully.', 'Use it to help partners agree on a supportive plan for days when one of them feels low.', array['Couples']::text[], '30 minutes', 'Have the partner who has heavy days say what helps and what does not. The other partner says what they can offer and what they need. Write a short signal and a menu. If either mentions thoughts of self-harm, include 988 (call or text) and complete safety planning in session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I will signal a heavy day"}, {"id": "f1", "type": "textarea", "label": "What helps me on those days"}, {"id": "f2", "type": "textarea", "label": "What does not help"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I can offer"}, {"id": "f4", "type": "textarea", "label": "Partner B: what I need too"}, {"id": "f5", "type": "textarea", "label": "Who else we can call, and 988 (call or text) in a crisis"}]'::jsonb, array['support', 'couples', 'communication', 'depression']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('launch-pad-task-starter', 'Launch Pad Task Starter', 'worksheet'::resource_kind, 'A client breaks a dreaded task into a first two-minute step and sets up the space and cue to begin.', 'Use it to help a client get a task started by shrinking the first step and preparing the setup.', array['Adults']::text[], '20 minutes', 'Pick a task the client has been putting off. Find the smallest first step, what the client needs nearby, and a cue to begin. Starting is the target, not finishing. Review what made starting easier or harder next time.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "The two-minute first step"}, {"id": "f2", "type": "textarea", "label": "What I need nearby"}, {"id": "f3", "type": "textarea", "label": "The cue that tells me to start"}, {"id": "f4", "type": "textarea", "label": "What I will do right after the first step"}]'::jsonb, array['task initiation', 'executive function', 'planning', 'ADHD']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('distraction-log-and-plan', 'Distraction Log and Plan', 'cbt'::resource_kind, 'A client logs what pulls them off task and plans a response to each common pull.', 'Use it to help a client spot their usual distractions and plan a response for each.', array['Adults']::text[], 'One week', 'The client notes time, task and what pulled their attention. At review, group the pulls and plan an if-then response for the top two. Keep the tone curious, not critical. Adjust the environment before relying on willpower.', '[{"id": "f0", "type": "textarea", "label": "The task I was on"}, {"id": "f1", "type": "textarea", "label": "What pulled my attention"}, {"id": "f2", "type": "textarea", "label": "How long until I noticed"}, {"id": "f3", "type": "textarea", "label": "What I did to get back"}, {"id": "f4", "type": "textarea", "label": "An if-then plan for next time"}]'::jsonb, array['attention', 'self-monitoring', 'core CBT', 'ADHD']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('values-over-the-urge-to-switch', 'Values Over the Urge to Switch', 'act'::resource_kind, 'A client notices the urge to switch tasks, names the value behind the task, and chooses whether to stay.', 'Use it to help a client notice an urge to switch and choose with their values in mind.', array['Adults']::text[], '20 minutes', 'The client tracks the urge to switch tasks and what they were leaving. They connect the task to something that matters and decide. Sometimes switching is the right call; the aim is choice. Experiment with a short timed stay.', '[{"id": "f0", "type": "textarea", "label": "The task and why it matters to me"}, {"id": "f1", "type": "textarea", "label": "The urge I noticed"}, {"id": "f2", "type": "textarea", "label": "What I told myself"}, {"id": "f3", "type": "textarea", "label": "What I chose to do"}, {"id": "f4", "type": "textarea", "label": "How the choice felt"}]'::jsonb, array['values', 'attention', 'core ACT', 'ADHD']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('mindful-single-tasking-practice', 'Mindful Single-Tasking Practice', 'dbt'::resource_kind, 'A client picks one everyday activity and practices doing only that, noticing each time attention drifts.', 'Use it to build the skill of noticing drift and returning to one thing at a time.', array['Adults']::text[], 'Ten minutes daily', 'Start with a short activity such as washing a mug. The client notes each time attention wanders and returns without scolding. Expect many returns and count them as practice. Increase the length slowly.', '[{"id": "f0", "type": "textarea", "label": "The activity I chose"}, {"id": "f1", "type": "textarea", "label": "How many times I drifted"}, {"id": "f2", "type": "textarea", "label": "What pulled me away"}, {"id": "f3", "type": "textarea", "label": "How I came back"}, {"id": "f4", "type": "textarea", "label": "What I noticed about doing one thing"}]'::jsonb, array['mindfulness', 'attention', 'core DBT', 'ADHD']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('beat-the-clock-chore-race', 'Beat the Clock Chore Race', 'game'::resource_kind, 'A timed game where a family or group races a timer on small tasks and celebrates beating personal bests.', 'Use it to make short tasks feel like a game for clients who work better with time and novelty.', array['Children', 'Groups']::text[], '20 minutes', 'Pick small tasks and a visible timer. Players race their own time, never each other. Celebrate improvement and effort. If a parent joins, the parent also takes a turn so the game stays shared. Debrief on what made it easier to start.', '[{"id": "f0", "type": "textarea", "label": "The task I raced"}, {"id": "f1", "type": "textarea", "label": "My time and my best time"}, {"id": "f2", "type": "textarea", "label": "What helped me start"}, {"id": "f3", "type": "textarea", "label": "What got in the way"}, {"id": "f4", "type": "textarea", "label": "A task I will race at home"}]'::jsonb, array['task initiation', 'play', 'children', 'ADHD']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('urge-rise-and-fall-tracker', 'Urge Rise and Fall Tracker', 'worksheet'::resource_kind, 'A client tracks when urges rise, how strong they get, what they did, and when they passed.', 'Use it to help a client see how urges rise and fall and what helps them pass.', array['Adults']::text[], 'One week', 'Ask the client to jot time, setting, strength from 0 to 10 and what they did. At review, look for patterns of time, place and feeling, and notice any urge that passed without action. Speak about substance use and urges, not labels. Celebrate every noticed urge.', '[{"id": "f0", "type": "textarea", "label": "When the urge started and where I was"}, {"id": "f1", "type": "textarea", "label": "How strong it got, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "How long until it eased"}, {"id": "f4", "type": "textarea", "label": "What I would try next time"}]'::jsonb, array['urges', 'substance use', 'self-monitoring', 'addiction']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('if-then-plans-for-high-risk-moments', 'If-Then Plans for High-Risk Moments', 'cbt'::resource_kind, 'A client writes if-then plans for the situations where substance use is most likely.', 'Use it to help a client prepare a specific action for each high-risk moment.', array['Adults']::text[], '30 minutes', 'List the top three risky moments with the client. For each write an if-then step that is concrete and easy. Rehearse one aloud. Revisit what worked and what did not. Slips are information, not failure.', '[{"id": "f0", "type": "textarea", "label": "A moment when substance use is more likely"}, {"id": "f1", "type": "textarea", "label": "If that happens, then I will"}, {"id": "f2", "type": "textarea", "label": "Who I can contact"}, {"id": "f3", "type": "textarea", "label": "What I will remind myself"}, {"id": "f4", "type": "textarea", "label": "How I will reward myself for using the plan"}]'::jsonb, array['relapse prevention', 'planning', 'substance use', 'addiction']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('life-beyond-substance-use-values-map', 'Life Beyond Substance Use Values Map', 'act'::resource_kind, 'A client maps what matters to them in several areas of life and which actions fit each.', 'Use it to help a client link actions to what they care about beyond substance use.', array['Adults']::text[], '30 minutes', 'Choose three life areas such as family, health and work. Fill in a value and one action for each. Note where substance use pulls away from them, without judging. Pick the area where a small action would matter most.', '[{"id": "f0", "type": "textarea", "label": "An area of life I care about"}, {"id": "f1", "type": "textarea", "label": "What matters to me there"}, {"id": "f2", "type": "textarea", "label": "An action that fits"}, {"id": "f3", "type": "textarea", "label": "How substance use pulls on it"}, {"id": "f4", "type": "textarea", "label": "The first small step this week"}]'::jsonb, array['values', 'committed action', 'substance use', 'addiction']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('urge-delay-and-distract-menu', 'Urge Delay and Distract Menu', 'dbt'::resource_kind, 'A client builds a menu of ways to delay acting on an urge and shift attention in the meantime.', 'Use it to give a client a ready set of choices for the minutes when an urge is strong.', array['Adults']::text[], '25 minutes', 'The client lists quick things that change body and attention such as cold water, a walk or a call. Set a delay time, such as ten minutes, and review how the urge changed. Keep the menu where it is easy to find.', '[{"id": "f0", "type": "textarea", "label": "Things that change my body state fast"}, {"id": "f1", "type": "textarea", "label": "Things that shift my attention"}, {"id": "f2", "type": "textarea", "label": "People I can contact"}, {"id": "f3", "type": "textarea", "label": "How long I will delay"}, {"id": "f4", "type": "textarea", "label": "What I noticed after the delay"}]'::jsonb, array['urges', 'distress tolerance', 'substance use', 'addiction']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('support-without-policing-agreement', 'Support Without Policing Agreement', 'couples'::resource_kind, 'Partners agree on how one can help with recovery goals without checking up or lecturing.', 'Use it to help partners agree on supportive roles that avoid policing and blame.', array['Couples']::text[], '40 minutes', 'The partner working on substance use says what helps and what feels like pressure. The other partner names worries and what they need. Together write a short agreement and a plan for hard moments. Keep it about shared goals.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me"}, {"id": "f1", "type": "textarea", "label": "Partner A: what feels like pressure"}, {"id": "f2", "type": "textarea", "label": "Partner B: what worries me"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I can offer"}, {"id": "f4", "type": "textarea", "label": "How we will check in without blame"}]'::jsonb, array['support', 'communication', 'substance use', 'addiction']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('anger-rungs-body-cue-sheet', 'Anger Rungs Body Cue Sheet', 'worksheet'::resource_kind, 'A client rates anger from low to high with body cues and a skill for each rung.', 'Use it to help a client notice anger early and match a skill to each level.', array['Adults']::text[], '25 minutes', 'Draw a ladder with five rungs. For each rung the client names the body cue, thought and a skill to use. The earlier rungs get quick skills; the top rung gets leaving the room. Practice naming a rung during the week.', '[{"id": "f0", "type": "textarea", "label": "Rung one: what it feels like and my skill"}, {"id": "f1", "type": "textarea", "label": "Rung three: what it feels like and my skill"}, {"id": "f2", "type": "textarea", "label": "Rung five: what it feels like and my skill"}, {"id": "f3", "type": "textarea", "label": "Where I usually notice it"}, {"id": "f4", "type": "textarea", "label": "What I will try first"}]'::jsonb, array['de-escalation', 'self-monitoring', 'skills', 'anger management']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('demand-versus-preference-rewrite', 'Demand Versus Preference Rewrite', 'cbt'::resource_kind, 'A client turns an angry demand into a clear preference and a request.', 'Use it to help a client turn a rigid demand into a preference they can ask for.', array['Adults']::text[], '20 minutes', 'Take a recent angry moment. Write the demand, then the preference under it, then a calm request. Notice how the body responds to the new wording. This is not about suppressing anger but about expressing it usefully.', '[{"id": "f0", "type": "textarea", "label": "What I demanded"}, {"id": "f1", "type": "textarea", "label": "The preference under it"}, {"id": "f2", "type": "textarea", "label": "How I could ask for it calmly"}, {"id": "f3", "type": "textarea", "label": "How the new wording feels"}, {"id": "f4", "type": "textarea", "label": "When I might use it"}]'::jsonb, array['thinking traps', 'communication', 'core CBT', 'anger management']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('anger-and-values-reflection', 'Anger and Values Reflection', 'act'::resource_kind, 'A client looks at what anger is protecting and chooses an action that fits their values.', 'Use it to help a client look at what anger is about and choose a response that fits their values.', array['Adults']::text[], '25 minutes', 'Anger often points at something that matters. Ask what the client was protecting. Then ask what response would fit that value. Make room for the feeling before action. Rehearse the new response briefly.', '[{"id": "f0", "type": "textarea", "label": "A recent time I was angry"}, {"id": "f1", "type": "textarea", "label": "What mattered to me there"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "An action that fits my values"}, {"id": "f4", "type": "textarea", "label": "What I will practice"}]'::jsonb, array['values', 'committed action', 'core ACT', 'anger management']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('stop-and-take-a-break-card', 'STOP and Take a Break Card', 'dbt'::resource_kind, 'A pocket card for the STOP skill with a plan for stepping away and returning calmly.', 'Use it to give a client a short script for pausing before acting in anger.', array['Adults']::text[], '15 minutes', 'Teach STOP: stop, take a step back, observe, proceed mindfully. The client writes their own words on the card and rehearses. Agree on how to say they need a break and when they will return. Practice with a mildly annoying scenario.', '[{"id": "f0", "type": "textarea", "label": "What I say when I need a break"}, {"id": "f1", "type": "textarea", "label": "Where I will go"}, {"id": "f2", "type": "textarea", "label": "What I will do for ten minutes"}, {"id": "f3", "type": "textarea", "label": "What I will notice"}, {"id": "f4", "type": "textarea", "label": "How I will return to the conversation"}]'::jsonb, array['de-escalation', 'mindfulness', 'core DBT', 'anger management']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('anger-dial-building-craft', 'Anger Dial Building Craft', 'kids'::resource_kind, 'A child makes a thermometer with colors for anger levels and attaches a calming idea to each.', 'Use it to help a child notice how big anger is and pick a calming idea for that size.', array['Children']::text[], '30 minutes', 'The child colors a paper thermometer from cool to hot and adds ideas such as breathing, squeezing a pillow or asking for space. The parent practices one idea with them at a calm time. At home, the parent can ask what number the child is at.', '[{"id": "f0", "type": "textarea", "label": "What my anger feels like at a small level"}, {"id": "f1", "type": "textarea", "label": "What my anger feels like at a big level"}, {"id": "f2", "type": "textarea", "label": "What helps at each level"}, {"id": "f3", "type": "textarea", "label": "Who can help me"}, {"id": "f4", "type": "textarea", "label": "My favorite idea"}]'::jsonb, array['children', 'de-escalation', 'art', 'anger management']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('compulsion-cost-ledger', 'Compulsion Cost Ledger', 'worksheet'::resource_kind, 'A client lists the time, energy and activities that compulsions take and what they would do with that time.', 'Use it to help a client see what compulsions cost and what they might do instead.', array['Adults']::text[], '25 minutes', 'Ask for an honest tally of time and what is given up. Then ask what the client would do with the time. Use it to build motivation for exposure work, which you plan separately. Do not push; invite.', '[{"id": "f0", "type": "textarea", "label": "A compulsion I do and how often"}, {"id": "f1", "type": "textarea", "label": "How much time it takes"}, {"id": "f2", "type": "textarea", "label": "What it costs me"}, {"id": "f3", "type": "textarea", "label": "What I would do with the time"}, {"id": "f4", "type": "textarea", "label": "What matters to me that it gets in the way of"}]'::jsonb, array['compulsions', 'values', 'self-monitoring', 'OCD']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('uncertainty-tolerance-experiment', 'Uncertainty Tolerance Experiment', 'cbt'::resource_kind, 'A client plans an experiment of sitting with not knowing and records what happens.', 'Use it to help a client practice tolerating not knowing in a planned, small way.', array['Adults']::text[], '25 minutes', 'Choose a small uncertainty the client usually resolves by checking or reassurance. Agree on the experiment: wait or leave it unresolved. The client predicts what will happen and logs the result. Review the prediction against the outcome.', '[{"id": "f0", "type": "textarea", "label": "The uncertainty I will leave open"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen"}, {"id": "f2", "type": "textarea", "label": "What I did instead of checking"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I learned about not knowing"}]'::jsonb, array['uncertainty', 'behavioral experiment', 'core CBT', 'OCD']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('making-room-for-doubt-practice', 'Making Room for Doubt Practice', 'act'::resource_kind, 'A client practices noticing doubt as a thought and continuing an action that matters.', 'Use it to help a client let doubt come along while acting on what matters.', array['Adults']::text[], '20 minutes', 'The client labels doubt as a thought, thanks the mind, and does a valued action anyway. Practice with a real doubt in session. Review how it felt and what pulled the client toward certainty.', '[{"id": "f0", "type": "textarea", "label": "The doubt I notice"}, {"id": "f1", "type": "textarea", "label": "How I label it"}, {"id": "f2", "type": "textarea", "label": "A valued action I will do with doubt present"}, {"id": "f3", "type": "textarea", "label": "What pulled me toward certainty"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['defusion', 'uncertainty', 'core ACT', 'OCD']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('response-delay-timer-plan', 'Response Delay Timer Plan', 'dbt'::resource_kind, 'A client builds a stepwise plan to delay a compulsion and extend the delay a little each week.', 'Use it to help a client lengthen the pause before a compulsion in small steps.', array['Adults']::text[], '25 minutes', 'Choose one compulsion the client is ready to delay. Agree on a short delay, then lengthen it. Name skills for the waiting time such as paced breathing. Review without judgment, and adjust when it is too steep.', '[{"id": "f0", "type": "textarea", "label": "The compulsion I will delay"}, {"id": "f1", "type": "textarea", "label": "Today''s delay in minutes"}, {"id": "f2", "type": "textarea", "label": "What I will do while I wait"}, {"id": "f3", "type": "textarea", "label": "How strong the urge was"}, {"id": "f4", "type": "textarea", "label": "Next week''s delay"}]'::jsonb, array['urges', 'distress tolerance', 'core DBT', 'OCD']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('bossy-brain-comic-strip', 'Bossy Brain Comic Strip', 'kids'::resource_kind, 'A child draws a comic where they talk back to a bossy brain voice with a parent as a sidekick.', 'Use it to help a child see worry as a voice they can talk back to.', array['Children']::text[], '30 minutes', 'The child draws panels with the bossy voice and a brave reply. The parent practices not giving reassurance and instead says they believe the child can handle it. Plan one small practice at home. Keep it fun.', '[{"id": "f0", "type": "textarea", "label": "What the bossy brain says"}, {"id": "f1", "type": "textarea", "label": "What I say back"}, {"id": "f2", "type": "textarea", "label": "What my sidekick does"}, {"id": "f3", "type": "textarea", "label": "What I did instead of what it said"}, {"id": "f4", "type": "textarea", "label": "How I feel after"}]'::jsonb, array['children', 'externalizing', 'play', 'OCD']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('first-panic-wave-story-sheet', 'First Panic Wave Story Sheet', 'worksheet'::resource_kind, 'A client writes about what happens in the body and mind during a panic surge and what makes it pass.', 'Use it to help a client describe the shape of a panic surge in plain words.', array['Adults']::text[], '20 minutes', 'Ask the client to describe a recent surge in time order: what came first, the peak and the way down. Look for points where a skill could fit. Keep the details to body and thought, not catastrophes.', '[{"id": "f0", "type": "textarea", "label": "What I felt first"}, {"id": "f1", "type": "textarea", "label": "What my mind said"}, {"id": "f2", "type": "textarea", "label": "The peak"}, {"id": "f3", "type": "textarea", "label": "What helped it pass"}, {"id": "f4", "type": "textarea", "label": "What I would try next time"}]'::jsonb, array['body awareness', 'self-monitoring', 'breathing', 'panic attacks']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('sensation-meaning-swap', 'Sensation Meaning Swap', 'cbt'::resource_kind, 'A client lists the meanings they give to body sensations and tries more neutral explanations.', 'Use it to help a client try other explanations for body sensations during panic.', array['Adults']::text[], '20 minutes', 'List sensations such as a racing heart and the meaning the client gives. Brainstorm other explanations. Encourage the client to check with a medical provider about sensations that concern them. Experiment together.', '[{"id": "f0", "type": "textarea", "label": "A sensation I notice"}, {"id": "f1", "type": "textarea", "label": "What I think it means"}, {"id": "f2", "type": "textarea", "label": "Other possible reasons for it"}, {"id": "f3", "type": "textarea", "label": "What I know about it from my doctor"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself next time"}]'::jsonb, array['thinking traps', 'body awareness', 'core CBT', 'panic attacks']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('carrying-panic-on-a-walk', 'Carrying Panic on a Walk', 'act'::resource_kind, 'A client plans a short walk while allowing sensations to come along and noting what they notice.', 'Use it to help a client do something that matters while panic sensations are allowed to be present.', array['Adults']::text[], '25 minutes', 'Choose a walk or errand the client has been avoiding. Plan which sensations may appear and how they will make room. Keep it short and increase gradually. Review what they noticed and what mattered.', '[{"id": "f0", "type": "textarea", "label": "The walk I will take"}, {"id": "f1", "type": "textarea", "label": "Sensations I might feel"}, {"id": "f2", "type": "textarea", "label": "How I will make room"}, {"id": "f3", "type": "textarea", "label": "What matters about doing this"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['willingness', 'exposure', 'core ACT', 'panic attacks']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('temperature-reset-card-for-surges', 'Temperature Reset Card for Surges', 'dbt'::resource_kind, 'A card for using cold water or temperature change to bring the body down during a surge.', 'Use it to give a client a quick body-based reset during a surge of panic.', array['Adults']::text[], '15 minutes', 'Teach the temperature skill in session and ask the client to check with a doctor first if they have health concerns. Practice with a cold pack on the cheeks. Pair it with paced breathing. Plan where to keep supplies.', '[{"id": "f0", "type": "textarea", "label": "Where I will keep cold water or a cold pack"}, {"id": "f1", "type": "textarea", "label": "When I will use it"}, {"id": "f2", "type": "textarea", "label": "What I notice in my body"}, {"id": "f3", "type": "textarea", "label": "What I do next"}, {"id": "f4", "type": "textarea", "label": "How it worked"}]'::jsonb, array['distress tolerance', 'breathing', 'core DBT', 'panic attacks']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('surge-surfing-cards', 'Surge Surfing Cards', 'game'::resource_kind, 'Players draw cards with a body sensation and talk through a skill and a kind thought for riding it out.', 'Use it to practice talking through panic skills in a low-pressure group game.', array['Groups']::text[], '30 minutes', 'Make cards with sensations such as a pounding heart or tight chest. Players draw one and describe a skill and a kind thing to say. Others add suggestions. Debrief with which skill each person will practice this week.', '[{"id": "f0", "type": "textarea", "label": "The card I drew"}, {"id": "f1", "type": "textarea", "label": "The skill I would use"}, {"id": "f2", "type": "textarea", "label": "The kind thing I would say"}, {"id": "f3", "type": "textarea", "label": "A skill someone else said that I liked"}, {"id": "f4", "type": "textarea", "label": "What I will practice"}]'::jsonb, array['body awareness', 'group', 'play', 'panic attacks']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('praise-spotting-log', 'Praise Spotting Log', 'worksheet'::resource_kind, 'A parent logs specific moments of good behavior and the exact words they used to notice them.', 'Use it to help a parent notice and name what their child does well.', array['Adults']::text[], 'One week', 'Ask the parent to note one specific behavior a day and how they commented on it. Review for specificity and warmth. Many parents find it easier to correct than to praise; be encouraging about the shift. Keep it brief.', '[{"id": "f0", "type": "textarea", "label": "What my child did well today"}, {"id": "f1", "type": "textarea", "label": "What I said"}, {"id": "f2", "type": "textarea", "label": "How my child responded"}, {"id": "f3", "type": "textarea", "label": "A moment I missed"}, {"id": "f4", "type": "textarea", "label": "What I will notice tomorrow"}]'::jsonb, array['praise', 'communication', 'routines', 'parenting']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('parent-trigger-and-pause-plan', 'Parent Trigger and Pause Plan', 'cbt'::resource_kind, 'A parent identifies moments that spark strong reactions and plans a pause before responding.', 'Use it to help a parent plan a pause for moments when they react strongly.', array['Adults']::text[], '25 minutes', 'List the situations that most often spark a strong reaction and the thought behind it. Plan a pause: a breath, a phrase or stepping away briefly. Practice one in session. Review without shame.', '[{"id": "f0", "type": "textarea", "label": "A moment that sparks me"}, {"id": "f1", "type": "textarea", "label": "The thought I have"}, {"id": "f2", "type": "textarea", "label": "What I usually do"}, {"id": "f3", "type": "textarea", "label": "My pause"}, {"id": "f4", "type": "textarea", "label": "What I will say after"}]'::jsonb, array['thinking traps', 'self-compassion', 'core CBT', 'parenting']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('parenting-values-and-repair-page', 'Parenting Values and Repair Page', 'act'::resource_kind, 'A parent names the parent they want to be and plans a repair after a hard moment.', 'Use it to help a parent choose how to repair and reconnect after a hard moment.', array['Adults']::text[], '25 minutes', 'Ask what kind of parent the client wants to be, then what repair would look like after a rough moment. Repair is a simple acknowledgment and reconnection. Role-play a short repair statement. Keep it kind.', '[{"id": "f0", "type": "textarea", "label": "The parent I want to be"}, {"id": "f1", "type": "textarea", "label": "A recent hard moment"}, {"id": "f2", "type": "textarea", "label": "What repair could sound like"}, {"id": "f3", "type": "textarea", "label": "When I will do it"}, {"id": "f4", "type": "textarea", "label": "How I will treat myself afterwards"}]'::jsonb, array['values', 'repair', 'core ACT', 'parenting']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('co-parent-hand-off-agreement', 'Co-Parent Hand-Off Agreement', 'couples'::resource_kind, 'Two parents agree on routines, signals and ways to back each other up during busy parts of the day.', 'Use it to help co-parents agree on how to share the load and support each other.', array['Couples']::text[], '40 minutes', 'Each parent names a hard time of the day and what they need. Together they write a plan for hand-offs and a signal for needing support. Keep disagreements about parenting style for later. Check in again after a week.', '[{"id": "f0", "type": "textarea", "label": "Parent A: a hard time of the day"}, {"id": "f1", "type": "textarea", "label": "Parent B: a hard time of the day"}, {"id": "f2", "type": "textarea", "label": "How we will hand off"}, {"id": "f3", "type": "textarea", "label": "Our signal for needing help"}, {"id": "f4", "type": "textarea", "label": "When we will check in"}]'::jsonb, array['routines', 'communication', 'couples', 'parenting']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('family-clothespin-feelings-chart', 'Family Clothespin Feelings Chart', 'kids'::resource_kind, 'A child and parent set up a simple chart where family members place a marker each day for how they feel.', 'Use it to give a family a simple daily way to share feelings.', array['Children']::text[], '20 minutes', 'The family builds a chart with faces and clothespins or stickers. Each person adds a marker daily and may say why. The parent goes first and models honest, calm sharing. No one is required to explain.', '[{"id": "f0", "type": "textarea", "label": "How I feel today"}, {"id": "f1", "type": "textarea", "label": "What made me feel that way"}, {"id": "f2", "type": "textarea", "label": "What would help"}, {"id": "f3", "type": "textarea", "label": "Who I want to tell"}, {"id": "f4", "type": "textarea", "label": "How I felt seeing others'' markers"}]'::jsonb, array['children', 'family', 'emotion identification', 'parenting']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('perfect-parent-expectations-check', 'Perfect Parent Expectations Check', 'cbt'::resource_kind, 'A new parent lists the expectations they hold and tests which ones help and which only add pressure.', 'Use it to help a new parent loosen expectations that add pressure.', array['Adults']::text[], '25 minutes', 'Ask for the unwritten rules the parent holds, such as always being calm. Sort into helpful and pressuring, and rewrite a few kindly. Normalize that early parenthood is demanding. If a parent mentions thoughts of self-harm, use 988 (call or text) and involve their care team in session.', '[{"id": "f0", "type": "textarea", "label": "A rule I hold for myself as a parent"}, {"id": "f1", "type": "textarea", "label": "Where it came from"}, {"id": "f2", "type": "textarea", "label": "What it costs me"}, {"id": "f3", "type": "textarea", "label": "A kinder version"}, {"id": "f4", "type": "textarea", "label": "Who I can share this with, and 988 (call or text) if I feel unsafe"}]'::jsonb, array['thinking traps', 'self-compassion', 'core CBT', 'perinatal and postpartum']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('sleep-shifts-and-support-planner', 'Sleep Shifts and Support Planner', 'worksheet'::resource_kind, 'A planner where a new parent lists night and day tasks and who can take which shift for protected rest.', 'Use it to help a new parent build protected rest and clear help into the week.', array['Adults']::text[], '30 minutes', 'Lay out the week and mark when the parent can rest. List helpers by name and what each can do. Practice asking aloud for one specific thing. Revisit as the baby''s routine changes.', '[{"id": "f0", "type": "textarea", "label": "The hours I most need rest"}, {"id": "f1", "type": "textarea", "label": "Who can take a shift"}, {"id": "f2", "type": "textarea", "label": "Tasks I can hand off"}, {"id": "f3", "type": "textarea", "label": "How I will ask for help"}, {"id": "f4", "type": "textarea", "label": "One thing I will protect each day"}]'::jsonb, array['support', 'planning', 'routines', 'perinatal and postpartum']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('values-in-the-fog-of-early-parenthood', 'Values in the Fog of Early Parenthood', 'act'::resource_kind, 'A parent names a value to hold onto during exhausting days and a tiny action that honors it.', 'Use it to help a parent stay connected to what matters in very tired days.', array['Adults']::text[], '20 minutes', 'Acknowledge how heavy early parenting is. Ask what the parent wants to stand for in these months and what small action fits. Keep it tiny. Make room for the feelings that come with it.', '[{"id": "f0", "type": "textarea", "label": "What I want to stand for as a parent"}, {"id": "f1", "type": "textarea", "label": "A tiny action that fits"}, {"id": "f2", "type": "textarea", "label": "A hard feeling I make room for"}, {"id": "f3", "type": "textarea", "label": "Who can help me do it"}, {"id": "f4", "type": "textarea", "label": "How I will notice it"}]'::jsonb, array['values', 'committed action', 'core ACT', 'perinatal and postpartum']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('one-minute-calm-for-night-feeds', 'One-Minute Calm for Night Feeds', 'dbt'::resource_kind, 'A short skill card for a calm minute during night feeds using breath, senses and a kind phrase.', 'Use it to give a tired parent a very short skill for moments in the night.', array['Adults']::text[], '15 minutes', 'Practice it in session. The card has one slow breath, naming three things the parent can feel and a kind phrase. Suggest placing the card where feeds happen. Keep expectations small.', '[{"id": "f0", "type": "textarea", "label": "The three things I notice"}, {"id": "f1", "type": "textarea", "label": "My kind phrase"}, {"id": "f2", "type": "textarea", "label": "Where I will keep the card"}, {"id": "f3", "type": "textarea", "label": "How my body felt after"}, {"id": "f4", "type": "textarea", "label": "What I would change"}]'::jsonb, array['self-soothing', 'mindfulness', 'core DBT', 'perinatal and postpartum']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('partner-role-swap-conversation', 'Partner Role Swap Conversation', 'couples'::resource_kind, 'Partners talk about what each carries in the first months with a baby and agree on one swap.', 'Use it to help partners see each other''s load and share it more fairly.', array['Couples']::text[], '40 minutes', 'Each partner lists what they carry, visible and invisible. They read each other''s list aloud, then agree on one trade. Expect tiredness and short tempers. Keep sessions practical and warm.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I carry"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I carry"}, {"id": "f2", "type": "textarea", "label": "What surprised me about the other''s list"}, {"id": "f3", "type": "textarea", "label": "One swap we agree to try"}, {"id": "f4", "type": "textarea", "label": "When we will check in"}]'::jsonb, array['fairness', 'communication', 'couples', 'perinatal and postpartum']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('strengths-evidence-file', 'Strengths Evidence File', 'worksheet'::resource_kind, 'A client collects specific examples that show a strength in action across the week.', 'Use it to help a client build a record of the strengths they actually show.', array['Adults']::text[], 'One week', 'Pick two strengths with the client. Each day they add one specific example. Include small ones. At review, read them aloud together and notice how the client reacts to praise. Keep the file somewhere handy.', '[{"id": "f0", "type": "textarea", "label": "A strength I chose"}, {"id": "f1", "type": "textarea", "label": "An example from today"}, {"id": "f2", "type": "textarea", "label": "What it shows about me"}, {"id": "f3", "type": "textarea", "label": "Who noticed it"}, {"id": "f4", "type": "textarea", "label": "What I want to add tomorrow"}]'::jsonb, array['strengths', 'self-monitoring', 'evidence', 'self-esteem']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('core-belief-pie-slice', 'Core Belief Pie Slice', 'cbt'::resource_kind, 'A client divides a self-critical belief into pieces and sees what else contributes.', 'Use it to help a client see that a harsh self-judgment has many contributors, not just them.', array['Adults']::text[], '25 minutes', 'Take one self-critical belief. List everything that contributes to it, including other people, circumstances and chance. Draw a pie with the slices. Compare with the client''s first view and discuss how it feels.', '[{"id": "f0", "type": "textarea", "label": "The belief I judge myself by"}, {"id": "f1", "type": "textarea", "label": "All the things that played a part"}, {"id": "f2", "type": "textarea", "label": "My share and others'' shares"}, {"id": "f3", "type": "textarea", "label": "A fairer sentence"}, {"id": "f4", "type": "textarea", "label": "How I feel looking at it"}]'::jsonb, array['core beliefs', 'self-criticism', 'core CBT', 'self-esteem']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('self-as-context-pause', 'Self as Context Pause', 'act'::resource_kind, 'A client practices noticing they are the one who has the thoughts about themselves, not the thoughts.', 'Use it to help a client step back from harsh stories about themselves.', array['Adults']::text[], '20 minutes', 'Guide the client to notice thoughts as events passing in the mind. Ask them to watch a harsh story and then name who is watching. Keep it experiential. Invite them to repeat it in daily life.', '[{"id": "f0", "type": "textarea", "label": "A harsh story I tell about myself"}, {"id": "f1", "type": "textarea", "label": "What it is like to watch it"}, {"id": "f2", "type": "textarea", "label": "Who is doing the watching"}, {"id": "f3", "type": "textarea", "label": "What stays the same underneath"}, {"id": "f4", "type": "textarea", "label": "When I will practice this"}]'::jsonb, array['self-as-context', 'defusion', 'core ACT', 'self-esteem']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('validate-yourself-daily', 'Validate Yourself Daily', 'dbt'::resource_kind, 'A client writes a self-validating sentence each day that names a feeling and why it makes sense.', 'Use it to help a client acknowledge their own feelings in a kind, believable way.', array['Adults']::text[], 'Five minutes daily', 'Teach self-validation as acknowledging a feeling makes sense given the situation, without overstating it. The client writes one sentence a day. Review the wording for what feels believable.', '[{"id": "f0", "type": "textarea", "label": "What I felt today"}, {"id": "f1", "type": "textarea", "label": "Why it makes sense"}, {"id": "f2", "type": "textarea", "label": "A validating sentence"}, {"id": "f3", "type": "textarea", "label": "How it landed"}, {"id": "f4", "type": "textarea", "label": "Tomorrow''s feeling to notice"}]'::jsonb, array['validation', 'self-compassion', 'core DBT', 'self-esteem']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('things-i-am-good-at-poster', 'Things I Am Good At Poster', 'kids'::resource_kind, 'A child decorates a poster of what they are good at and what they are learning.', 'Use it to help a child see their strengths and growth in a display they made.', array['Children']::text[], '30 minutes', 'The child draws or lists what they do well and what they are learning. The parent adds one from their own view. Hang it in view. Praise effort and learning, not only results.', '[{"id": "f0", "type": "textarea", "label": "Something I am good at"}, {"id": "f1", "type": "textarea", "label": "Something I am learning"}, {"id": "f2", "type": "textarea", "label": "Something I did that I am proud of"}, {"id": "f3", "type": "textarea", "label": "Something a friend likes about me"}, {"id": "f4", "type": "textarea", "label": "Something I want to try"}]'::jsonb, array['children', 'strengths', 'art', 'self-esteem']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('safety-behaviors-spotting-page', 'Safety Behaviors Spotting Page', 'worksheet'::resource_kind, 'A client lists the small things they do to feel safer socially and what each costs them.', 'Use it to help a client notice habits that feel protective but may keep worry going.', array['Adults']::text[], '20 minutes', 'List behaviors such as rehearsing lines or avoiding eye contact. For each, note what it protects and what it costs. Choose one to drop in a small, planned experiment. Keep a nonjudgmental tone.', '[{"id": "f0", "type": "textarea", "label": "A small thing I do to feel safer"}, {"id": "f1", "type": "textarea", "label": "What it protects me from"}, {"id": "f2", "type": "textarea", "label": "What it costs"}, {"id": "f3", "type": "textarea", "label": "What I would do if I did not do it"}, {"id": "f4", "type": "textarea", "label": "A small experiment I will try"}]'::jsonb, array['avoidance', 'exposure', 'self-monitoring', 'social anxiety']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('social-event-balanced-review', 'Social Event Balanced Review', 'cbt'::resource_kind, 'A client reviews a social event with balanced questions instead of replaying every mistake.', 'Use it to help a client review a social event fairly and stop replaying it.', array['Adults']::text[], '20 minutes', 'Use it after a gathering. Ask for what went as planned, what the client noticed others doing, and what they would tell a friend. Compare with the harsh replay. Plan one thing to do differently, not ten.', '[{"id": "f0", "type": "textarea", "label": "What happened, in plain facts"}, {"id": "f1", "type": "textarea", "label": "What went okay"}, {"id": "f2", "type": "textarea", "label": "What others seemed to be doing"}, {"id": "f3", "type": "textarea", "label": "What I would tell a friend"}, {"id": "f4", "type": "textarea", "label": "One small thing to try next time"}]'::jsonb, array['thinking traps', 'social comparison', 'core CBT', 'social anxiety']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('values-driven-social-step', 'Values-Driven Social Step', 'act'::resource_kind, 'A client chooses a social step that expresses a value and does it with nerves present.', 'Use it to help a client take a social step that matters while nerves come along.', array['Adults']::text[], '25 minutes', 'The client picks a value such as friendship and a step like asking a question. Plan what nerves will say and how to hold them lightly. Rehearse the opening line. Review what happened.', '[{"id": "f0", "type": "textarea", "label": "A value I care about socially"}, {"id": "f1", "type": "textarea", "label": "The step I will take"}, {"id": "f2", "type": "textarea", "label": "What my nerves say"}, {"id": "f3", "type": "textarea", "label": "How I will carry them"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['values', 'connection', 'core ACT', 'social anxiety']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('social-outing-support-plan', 'Social Outing Support Plan', 'couples'::resource_kind, 'A partner learns how to support the other at a social event without rescuing or pushing.', 'Use it to help partners agree on helpful support during social events.', array['Couples']::text[], '30 minutes', 'The anxious partner names what helps before, during and after an outing. The other partner says what they can do and what they cannot. Agree on a signal and an exit plan. Review afterward.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps before"}, {"id": "f1", "type": "textarea", "label": "What helps during"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I can do"}, {"id": "f3", "type": "textarea", "label": "Our signal and exit plan"}, {"id": "f4", "type": "textarea", "label": "What we will review afterward"}]'::jsonb, array['support', 'couples', 'communication', 'social anxiety']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('conversation-starter-pass', 'Conversation Starter Pass', 'game'::resource_kind, 'Players pass a ball and answer light conversation cards, then share what helped them speak.', 'Use it to give a group low-stakes practice at starting and continuing conversations.', array['Groups']::text[], '25 minutes', 'Write friendly, simple cards such as a favorite meal. A player answers and passes the ball with a question. Allow passes. Debrief on what made it easier and what the body felt like.', '[{"id": "f0", "type": "textarea", "label": "The card I answered"}, {"id": "f1", "type": "textarea", "label": "How my body felt"}, {"id": "f2", "type": "textarea", "label": "What helped me speak"}, {"id": "f3", "type": "textarea", "label": "A question I liked"}, {"id": "f4", "type": "textarea", "label": "One conversation I will try this week"}]'::jsonb, array['social skills', 'group', 'play', 'social anxiety']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('grief-day-plan-page', 'Grief Day Plan Page', 'worksheet'::resource_kind, 'A client plans for an anniversary or hard date with what to do, who to be with and what to skip.', 'Use it to help a client plan ahead for a hard date with choices and support.', array['Adults']::text[], '25 minutes', 'Ask which dates are hard and what the client wants from them. Offer options: ritual, company, quiet or ordinary routine. Build in an easy exit. Check in afterward on what to keep next time.', '[{"id": "f0", "type": "textarea", "label": "The date and why it is hard"}, {"id": "f1", "type": "textarea", "label": "How I want to spend it"}, {"id": "f2", "type": "textarea", "label": "Who I want near"}, {"id": "f3", "type": "textarea", "label": "What I will leave out"}, {"id": "f4", "type": "textarea", "label": "A small way to honor my person"}]'::jsonb, array['support', 'planning', 'life review', 'grief and loss']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('should-haves-and-could-haves-review', 'Should Haves and Could Haves Review', 'cbt'::resource_kind, 'A client examines should-have thoughts about a loss and compares them with what was known then.', 'Use it to help a client look at guilt thoughts with what was known at the time.', array['Adults']::text[], '25 minutes', 'List should-have thoughts. For each, write what was known then and what hindsight adds. Keep a gentle pace and allow sadness. Do not argue away guilt; look for a fairer sentence.', '[{"id": "f0", "type": "textarea", "label": "A should-have thought"}, {"id": "f1", "type": "textarea", "label": "What I knew then"}, {"id": "f2", "type": "textarea", "label": "What I know now that I could not have known"}, {"id": "f3", "type": "textarea", "label": "A fairer sentence"}, {"id": "f4", "type": "textarea", "label": "What I want to say to myself"}]'::jsonb, array['guilt', 'thinking traps', 'core CBT', 'grief and loss']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('carrying-love-and-loss-together', 'Carrying Love and Loss Together', 'act'::resource_kind, 'A client writes what they miss and what they love, then picks an action that carries the love forward.', 'Use it to help a client hold love and pain together and act on what the love points toward.', array['Adults']::text[], '25 minutes', 'Grief is the other side of love. Ask what the client misses and what that shows they value. Choose an action that carries the value forward. Make room for the sadness that comes with it.', '[{"id": "f0", "type": "textarea", "label": "What I miss most"}, {"id": "f1", "type": "textarea", "label": "What that shows I value"}, {"id": "f2", "type": "textarea", "label": "An action that carries it on"}, {"id": "f3", "type": "textarea", "label": "The feeling I make room for"}, {"id": "f4", "type": "textarea", "label": "When I will do it"}]'::jsonb, array['values', 'acceptance', 'core ACT', 'grief and loss']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('wave-and-rest-skills-card', 'Wave and Rest Skills Card', 'dbt'::resource_kind, 'A card of skills for grief waves and for taking rests from grief during the day.', 'Use it to help a client ride grief waves and also take breaks from them.', array['Adults']::text[], '20 minutes', 'Both facing and resting from grief are normal. The card lists skills for waves and ways to rest such as a walk or a show. Practice one in session. Let the client decide the mix.', '[{"id": "f0", "type": "textarea", "label": "Skills for when a wave comes"}, {"id": "f1", "type": "textarea", "label": "Ways I rest from grief"}, {"id": "f2", "type": "textarea", "label": "People I can reach"}, {"id": "f3", "type": "textarea", "label": "What my body needs today"}, {"id": "f4", "type": "textarea", "label": "What I will try this week"}]'::jsonb, array['distress tolerance', 'self-soothing', 'core DBT', 'grief and loss']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('feelings-about-missing-someone-book', 'Feelings About Missing Someone Book', 'kids'::resource_kind, 'A child makes a small book of what they remember and feel about someone they miss.', 'Use it to help a child express memories and feelings about a loss through drawing.', array['Children']::text[], '30 minutes', 'The child makes a book with drawings. The parent shares memories too and says all feelings are okay. Keep language simple and honest. Let the child set the pace and stop any time.', '[{"id": "f0", "type": "textarea", "label": "Something I remember"}, {"id": "f1", "type": "textarea", "label": "What I miss"}, {"id": "f2", "type": "textarea", "label": "A feeling I have"}, {"id": "f3", "type": "textarea", "label": "Who I can talk to"}, {"id": "f4", "type": "textarea", "label": "Something I want to do to remember"}]'::jsonb, array['children', 'memory', 'art', 'grief and loss']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('pattern-spotting-between-us', 'Pattern Spotting Between Us', 'worksheet'::resource_kind, 'A client maps a repeating exchange with someone close into trigger, reaction and result.', 'Use it to help a client see a repeating relationship pattern as steps they can change.', array['Adults']::text[], '25 minutes', 'Choose a recent repeat of a familiar conflict. Map what set it off, what each person did and how it ended. Circle one step the client could do differently. Keep the focus on the client''s part, without blaming either person.', '[{"id": "f0", "type": "textarea", "label": "What set it off"}, {"id": "f1", "type": "textarea", "label": "What I did"}, {"id": "f2", "type": "textarea", "label": "What the other person did"}, {"id": "f3", "type": "textarea", "label": "How it ended"}, {"id": "f4", "type": "textarea", "label": "One step I could do differently"}]'::jsonb, array['conflict', 'communication', 'patterns', 'relationship issues']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('story-i-tell-about-them-check', 'Story I Tell About Them Check', 'cbt'::resource_kind, 'A client writes the story they tell about another person''s motives and tests it against what they know.', 'Use it to help a client check a story about another person''s motives against the facts.', array['Adults']::text[], '20 minutes', 'Ask for a recent moment when the client felt wronged. Separate the story from what was observed. List other possible reasons. Plan how to ask the person rather than assume.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "The story I told myself"}, {"id": "f2", "type": "textarea", "label": "What I actually know"}, {"id": "f3", "type": "textarea", "label": "Other possible reasons"}, {"id": "f4", "type": "textarea", "label": "How I could ask"}]'::jsonb, array['thinking traps', 'communication', 'core CBT', 'relationship issues']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('relationship-values-check-in', 'Relationship Values Check-In', 'act'::resource_kind, 'A client rates how closely their actions match the relationship values they hold.', 'Use it to help a client check whether their actions match the kind of partner, friend or family member they want to be.', array['Adults']::text[], '25 minutes', 'Pick one relationship and a value such as honesty or care. The client rates how close their actions were this week. Choose a small action to narrow the gap. Hold the review kindly.', '[{"id": "f0", "type": "textarea", "label": "The relationship I chose"}, {"id": "f1", "type": "textarea", "label": "A value I want to bring"}, {"id": "f2", "type": "textarea", "label": "How close my actions were, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "One small action to narrow the gap"}, {"id": "f4", "type": "textarea", "label": "What might get in the way"}]'::jsonb, array['values', 'relationships', 'core ACT', 'relationship issues']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('two-sides-of-the-same-fight', 'Two Sides of the Same Fight', 'couples'::resource_kind, 'Partners separately write what each felt and needed in a recent conflict and swap pages.', 'Use it to help partners hear each other''s feelings and needs from a recent conflict.', array['Couples']::text[], '45 minutes', 'Each partner completes their side alone. Swap and read aloud with the other only listening. Then each says what they heard. Do not decide who was right. Close with one change each is willing to try.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I felt and needed"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I felt and needed"}, {"id": "f2", "type": "textarea", "label": "What I heard from my partner"}, {"id": "f3", "type": "textarea", "label": "What surprised me"}, {"id": "f4", "type": "textarea", "label": "One change each of us will try"}]'::jsonb, array['conflict', 'Gottman', 'couples', 'relationship issues']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('both-sides-scenario-cards', 'Both Sides Scenario Cards', 'game'::resource_kind, 'Players draw a short scenario and describe it from each person''s point of view.', 'Use it to give a group practice in seeing a situation from more than one side.', array['Groups']::text[], '30 minutes', 'Write short, neutral scenarios such as a friend who forgot to call. Players describe each person''s view and feeling. The group adds more. Debrief on how seeing both sides changes what you might say.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew"}, {"id": "f1", "type": "textarea", "label": "How person one might feel"}, {"id": "f2", "type": "textarea", "label": "How person two might feel"}, {"id": "f3", "type": "textarea", "label": "What I might say"}, {"id": "f4", "type": "textarea", "label": "What I will remember"}]'::jsonb, array['empathy', 'group', 'play', 'relationship issues']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('my-support-circle-map', 'My Support Circle Map', 'worksheet'::resource_kind, 'A client maps the people and places that feel supportive, with how each can help.', 'Use it to help a client see the supports they have and how to reach them.', array['Adults']::text[], '25 minutes', 'Draw circles for close, helpful and distant supports. Do not ask about what happened. Let the client decide who to include. Note how to reach each and plan one reach-out. Pace gently and check in on how the client feels.', '[{"id": "f0", "type": "textarea", "label": "People who feel supportive"}, {"id": "f1", "type": "textarea", "label": "How each can help"}, {"id": "f2", "type": "textarea", "label": "Places that feel safe"}, {"id": "f3", "type": "textarea", "label": "Who I could reach out to this week"}, {"id": "f4", "type": "textarea", "label": "What I need from support"}]'::jsonb, array['support', 'safety', 'stabilizing', 'sexual abuse']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('safe-thoughts-and-stuck-thoughts-sort', 'Safe Thoughts and Stuck Thoughts Sort', 'cbt'::resource_kind, 'A client sorts present-day thoughts into helpful and stuck ones, without recounting any events.', 'Use it to help a client sort present-day thoughts and find kinder ones, without going over the past.', array['Adults']::text[], '25 minutes', 'Keep to current thoughts and leave events out. The client writes thoughts and sorts them. Choose one stuck thought and write a kinder, true alternative. Ground first and last. Stop if distress rises.', '[{"id": "f0", "type": "textarea", "label": "A thought that feels stuck"}, {"id": "f1", "type": "textarea", "label": "A thought that feels helpful"}, {"id": "f2", "type": "textarea", "label": "How I feel when I read the stuck one"}, {"id": "f3", "type": "textarea", "label": "A kinder, true alternative"}, {"id": "f4", "type": "textarea", "label": "A grounding step I will use"}]'::jsonb, array['thinking traps', 'stabilizing', 'core CBT', 'sexual abuse']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('choosing-pace-and-direction-page', 'Choosing Pace and Direction Page', 'act'::resource_kind, 'A client chooses what matters to them and a gentle pace for moving toward it.', 'Use it to help a client take back choice about pace while moving toward what matters.', array['Adults']::text[], '25 minutes', 'Emphasize choice and control over pace. Ask what the client wants more of in life and one small step. Check in on how fast or slow feels right. Remind the client they can pause at any time.', '[{"id": "f0", "type": "textarea", "label": "What matters to me"}, {"id": "f1", "type": "textarea", "label": "A gentle step toward it"}, {"id": "f2", "type": "textarea", "label": "The pace that feels right"}, {"id": "f3", "type": "textarea", "label": "What I will do if it feels too fast"}, {"id": "f4", "type": "textarea", "label": "Who I can tell"}]'::jsonb, array['values', 'pacing', 'stabilizing', 'sexual abuse']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('grounding-bridge-skills-card', 'Grounding Bridge Skills Card', 'dbt'::resource_kind, 'A card that bridges from a hard moment to the present using breath, senses and orientation.', 'Use it to help a client move from a hard moment to the present with simple steps.', array['Adults']::text[], '20 minutes', 'Practice in session. The card steps are feeling the feet, naming five things in the room, and a slow out breath. Adapt for the client''s comfort. If an episode feels unsafe, bring in supports; 988 (call or text) is available.', '[{"id": "f0", "type": "textarea", "label": "Where I feel my feet"}, {"id": "f1", "type": "textarea", "label": "Five things I can see"}, {"id": "f2", "type": "textarea", "label": "What I say to myself"}, {"id": "f3", "type": "textarea", "label": "Who I can contact, or 988 (call or text)"}, {"id": "f4", "type": "textarea", "label": "What helped most"}]'::jsonb, array['grounding', 'distress tolerance', 'stabilizing', 'sexual abuse']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('my-safe-grown-ups-hand', 'My Safe Grown-Ups Hand', 'kids'::resource_kind, 'A child traces a hand and names a safe grown-up on each finger and how to reach them.', 'Use it to help a child name the grown-ups they can go to when something feels wrong.', array['Children']::text[], '20 minutes', 'The child traces a hand and writes a safe adult on each finger. If a child discloses anything, stay calm, listen, and follow your reporting duties. The parent reviews the hand and reminds the child that telling is always okay.', '[{"id": "f0", "type": "textarea", "label": "A grown-up I can tell"}, {"id": "f1", "type": "textarea", "label": "Another grown-up I can tell"}, {"id": "f2", "type": "textarea", "label": "A place that feels safe"}, {"id": "f3", "type": "textarea", "label": "What I can say if I need help"}, {"id": "f4", "type": "textarea", "label": "Who helps me feel safe"}]'::jsonb, array['children', 'safety', 'art', 'sexual abuse']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('skill-fit-finder', 'Skill Fit Finder', 'worksheet'::resource_kind, 'A client rates coping skills on how fast they work, how easy they are and where they can use them.', 'Use it to help a client choose coping skills that fit their real life.', array['Adults']::text[], '25 minutes', 'List five skills the client has tried. Rate speed, ease and where they work. Choose a go-to for each setting. Keep the rating honest. Revisit regularly.', '[{"id": "f0", "type": "textarea", "label": "A skill I have tried"}, {"id": "f1", "type": "textarea", "label": "How fast it works, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "How easy it is, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Where I can use it"}, {"id": "f4", "type": "textarea", "label": "My go-to skills for work, home and out"}]'::jsonb, array['skills', 'self-monitoring', 'planning', 'coping skills']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('coping-statements-card-deck', 'Coping Statements Card Deck', 'cbt'::resource_kind, 'A client writes a deck of short, believable statements to say in hard moments.', 'Use it to give a client believable phrases to say when a moment is hard.', array['Adults']::text[], '25 minutes', 'The client writes statements that sound true to them, not slogans. Test each by reading aloud and rating how believable it is. Keep the believable ones on cards. Practice with a mild moment.', '[{"id": "f0", "type": "textarea", "label": "A hard moment"}, {"id": "f1", "type": "textarea", "label": "A statement I find believable"}, {"id": "f2", "type": "textarea", "label": "How believable, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "A stronger version"}, {"id": "f4", "type": "textarea", "label": "Where I will keep the card"}]'::jsonb, array['self-talk', 'cognitive restructuring', 'core CBT', 'coping skills']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('workability-check-of-my-coping', 'Workability Check of My Coping', 'act'::resource_kind, 'A client reviews a coping habit and asks whether it moves them toward what matters.', 'Use it to help a client ask whether a coping habit helps in the long run.', array['Adults']::text[], '25 minutes', 'Choose one coping habit. Ask what it gets the client now and what it costs later. Ask whether it moves them toward what matters. Do not judge; just observe. Consider adding another option.', '[{"id": "f0", "type": "textarea", "label": "The coping habit"}, {"id": "f1", "type": "textarea", "label": "What it gets me now"}, {"id": "f2", "type": "textarea", "label": "What it costs later"}, {"id": "f3", "type": "textarea", "label": "Does it move me toward what matters"}, {"id": "f4", "type": "textarea", "label": "One more option to try"}]'::jsonb, array['workability', 'values', 'core ACT', 'coping skills']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('distress-tolerance-toolbox-builder', 'Distress Tolerance Toolbox Builder', 'dbt'::resource_kind, 'A client assembles a toolbox of distraction, soothing, improving and accepting skills for crisis-level stress.', 'Use it to help a client build a toolbox of skills for getting through the worst moments.', array['Adults']::text[], '30 minutes', 'Walk through the categories. The client fills each with ideas they would actually use. Build a physical or phone-based version. If the client ever feels unsafe, use the plan and 988 (call or text). Practice one skill together.', '[{"id": "f0", "type": "textarea", "label": "Distract ideas"}, {"id": "f1", "type": "textarea", "label": "Soothe ideas"}, {"id": "f2", "type": "textarea", "label": "Improve the moment ideas"}, {"id": "f3", "type": "textarea", "label": "Accept ideas"}, {"id": "f4", "type": "textarea", "label": "Who I can contact, and 988 (call or text) if I feel unsafe"}]'::jsonb, array['distress tolerance', 'skills', 'core DBT', 'coping skills']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('skills-charades-showdown', 'Skills Charades Showdown', 'game'::resource_kind, 'Players act out a coping skill without words while the group guesses and shares when they use it.', 'Use it to refresh a group''s coping skills through a playful guessing game.', array['Groups']::text[], '25 minutes', 'Write skills on cards. Players act, the group guesses, and the actor shares a time they used it. Allow passes. Debrief on which skill each person will use this week.', '[{"id": "f0", "type": "textarea", "label": "The skill I acted"}, {"id": "f1", "type": "textarea", "label": "A time I used it"}, {"id": "f2", "type": "textarea", "label": "A skill I want to remember"}, {"id": "f3", "type": "textarea", "label": "A skill I will use this week"}]'::jsonb, array['skills', 'group', 'play', 'coping skills']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('fear-ladder-builder', 'Fear Ladder Builder', 'worksheet'::resource_kind, 'A client lists feared situations from easy to hard and rates the distress of each.', 'Use it to help a client build a step-by-step ladder of feared situations.', array['Adults']::text[], '30 minutes', 'List at least eight situations and rate each from 0 to 100. Order them and choose a first rung that feels challenging but doable. Plan how to stay in the step and what to expect. Review each step before moving on.', '[{"id": "f0", "type": "textarea", "label": "The fear I am working on"}, {"id": "f1", "type": "textarea", "label": "Situations from easiest to hardest"}, {"id": "f2", "type": "textarea", "label": "Rating for each"}, {"id": "f3", "type": "textarea", "label": "My first rung"}, {"id": "f4", "type": "textarea", "label": "What I will do to stay with it"}]'::jsonb, array['hierarchy', 'exposure', 'avoidance', 'phobias']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('fear-prediction-test-card', 'Fear Prediction Test Card', 'cbt'::resource_kind, 'A client writes what they predict will happen in a feared situation and compares it to what did.', 'Use it to help a client compare a feared prediction with what really happens.', array['Adults']::text[], '20 minutes', 'Before an exposure step the client writes the prediction and a rating. After it, record what happened. Compare and discuss. Repeat to build new information.', '[{"id": "f0", "type": "textarea", "label": "What I predict will happen"}, {"id": "f1", "type": "textarea", "label": "How sure I am, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What actually happened"}, {"id": "f3", "type": "textarea", "label": "What I learned"}, {"id": "f4", "type": "textarea", "label": "My next step"}]'::jsonb, array['behavioral experiment', 'exposure', 'core CBT', 'phobias']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('fear-and-freedom-choice-point', 'Fear and Freedom Choice Point', 'act'::resource_kind, 'A client maps what fear pulls them toward and what a valued action would be instead.', 'Use it to help a client see the choice between what fear pulls them toward and what matters.', array['Adults']::text[], '25 minutes', 'Draw a choice point with the feared situation in the middle. On one side list what fear pulls toward, on the other what matters. Choose a step toward the right side. Practice willingness.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "What fear pulls me toward"}, {"id": "f2", "type": "textarea", "label": "What matters to me"}, {"id": "f3", "type": "textarea", "label": "A step toward what matters"}, {"id": "f4", "type": "textarea", "label": "What I will make room for"}]'::jsonb, array['values', 'willingness', 'core ACT', 'phobias']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('calm-co-pilot-plan', 'Calm Co-Pilot Plan', 'couples'::resource_kind, 'A partner learns to be a calm presence during a planned exposure step without pushing or taking over.', 'Use it to help a partner support a feared step in a calm, steady way.', array['Couples']::text[], '30 minutes', 'The client says what helps and what does not. The partner practices short, calm phrases and not rescuing. Plan the step together. Review afterward.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me"}, {"id": "f1", "type": "textarea", "label": "What does not help"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I can say"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I will not do"}, {"id": "f4", "type": "textarea", "label": "How we will review"}]'::jsonb, array['support', 'exposure', 'couples', 'phobias']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('brave-steps-bingo-card', 'Brave Steps Bingo Card', 'kids'::resource_kind, 'A child earns a stamp for each small brave step toward a feared thing and plays toward a bingo line.', 'Use it to help a child take small brave steps toward a feared thing, with a parent cheering.', array['Children']::text[], '30 minutes', 'Make a bingo card of small steps with the child. The parent cheers and does not push beyond the plan. Stamps are for trying, not for being unafraid. Celebrate a line with a family treat.', '[{"id": "f0", "type": "textarea", "label": "A small brave step"}, {"id": "f1", "type": "textarea", "label": "How scared I felt"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "Who cheered me on"}, {"id": "f4", "type": "textarea", "label": "The next step I want to try"}]'::jsonb, array['children', 'exposure', 'play', 'phobias']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('body-gratitude-and-function-list', 'Body Gratitude and Function List', 'worksheet'::resource_kind, 'A client lists what their body helps them do and feel each day.', 'Use it to help a client appreciate what their body does for them.', array['Adults']::text[], 'One week', 'The client lists daily things their body makes possible. Keep the focus on function and sensation, never on appearance. Review and read the list aloud. Notice how it feels to look at it.', '[{"id": "f0", "type": "textarea", "label": "Something my body did for me today"}, {"id": "f1", "type": "textarea", "label": "A sensation I enjoyed"}, {"id": "f2", "type": "textarea", "label": "Something I did with my body that I love"}, {"id": "f3", "type": "textarea", "label": "A thank you to my body"}, {"id": "f4", "type": "textarea", "label": "What I want to do more of"}]'::jsonb, array['self-compassion', 'gratitude', 'self-monitoring', 'body image']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('mirror-time-thought-notes', 'Mirror Time Thought Notes', 'cbt'::resource_kind, 'A client notes thoughts that arise when checking appearance and tries kinder, more neutral wording.', 'Use it to help a client spot harsh appearance thoughts and rewrite them kindly.', array['Adults']::text[], '25 minutes', 'The client notes when and how often they check and the thought that comes. Practice a neutral or kind alternative aloud. Avoid reviewing any body measurements or numbers. Plan less checking one step at a time.', '[{"id": "f0", "type": "textarea", "label": "When I check my appearance"}, {"id": "f1", "type": "textarea", "label": "The thought that shows up"}, {"id": "f2", "type": "textarea", "label": "How it makes me feel"}, {"id": "f3", "type": "textarea", "label": "A neutral or kind alternative"}, {"id": "f4", "type": "textarea", "label": "What I would rather do with that time"}]'::jsonb, array['self-talk', 'self-criticism', 'core CBT', 'body image']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('body-as-an-ally-practice', 'Body as an Ally Practice', 'act'::resource_kind, 'A client practices noticing the body as a partner in valued activities rather than an object to judge.', 'Use it to help a client treat the body as a partner in doing what matters.', array['Adults']::text[], '20 minutes', 'Choose a valued activity such as walking with a friend. The client practices noticing how the body helps. When judgmental thoughts come, label them and return. Review the experience.', '[{"id": "f0", "type": "textarea", "label": "A valued activity I want to do"}, {"id": "f1", "type": "textarea", "label": "How my body helps me do it"}, {"id": "f2", "type": "textarea", "label": "A judgmental thought that showed up"}, {"id": "f3", "type": "textarea", "label": "How I labeled it and returned"}, {"id": "f4", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['values', 'defusion', 'core ACT', 'body image']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('self-soothe-without-checking-kit', 'Self-Soothe Without Checking Kit', 'dbt'::resource_kind, 'A client builds a kit of senses-based comforts to use instead of checking or comparing appearance.', 'Use it to help a client reach for a comfort instead of checking or comparing.', array['Adults']::text[], '25 minutes', 'The client notices the urge to check or compare and picks a soothing activity for the moment. Fill the kit with items for each sense. Practice one in session. Review which comforts helped.', '[{"id": "f0", "type": "textarea", "label": "The urge I notice"}, {"id": "f1", "type": "textarea", "label": "A sight that soothes me"}, {"id": "f2", "type": "textarea", "label": "A sound that soothes me"}, {"id": "f3", "type": "textarea", "label": "A touch that soothes me"}, {"id": "f4", "type": "textarea", "label": "What I did instead of checking"}]'::jsonb, array['self-soothing', 'urges', 'core DBT', 'body image']::text[], '2026-10-09T15:00:00+00:00'::timestamptz),
  ('compliments-that-are-not-about-looks', 'Compliments That Are Not About Looks', 'game'::resource_kind, 'Players draw cards and give each other compliments about character, skills and kindness.', 'Use it to help a group practice noticing and saying what they value in each other beyond looks.', array['Groups']::text[], '25 minutes', 'Make cards prompting qualities such as courage or humor. Players give a compliment to the person next to them. Debrief on how it felt to give and receive. Keep appearance out of the game.', '[{"id": "f0", "type": "textarea", "label": "A compliment I gave"}, {"id": "f1", "type": "textarea", "label": "A compliment I received"}, {"id": "f2", "type": "textarea", "label": "How it felt to receive it"}, {"id": "f3", "type": "textarea", "label": "Something I value in myself"}, {"id": "f4", "type": "textarea", "label": "What I will do with this"}]'::jsonb, array['strengths', 'group', 'play', 'body image']::text[], '2026-10-09T15:00:00+00:00'::timestamptz)
